INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4549', 'spa', 'Derretir, disolver; en sentido figurado, desfallecer o perder el ánimo; en Hifil, hacer que se derrita de miedo. Un verbo vívido de disolución que tra', 'Derretir, disolver; en sentido figurado, desfallecer o perder el ánimo; en Hifil, hacer que se derrita de miedo. Un verbo vívido de disolución que transita sin esfuerzo entre el derretimiento físico y el colapso emocional. El maná se derrite al sol (Éx 16:21), la cera se derrite ante el fuego (Sal 68:2) y las montañas se disuelven ante la presencia de Dios (Mi 1:4), pero con igual frecuencia es el valor humano el que se derrite. Cuando el informe de los espías aterroriza a Israel, ''el corazón del pueblo se derritió'' (Jos 7:5). El Nifal domina con dieciocho ocurrencias que cubren tanto la disolución literal como la figurada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4550', 'spa', 'Jornada, etapa de marcha — acción de levantar campamento y viajar al siguiente punto; etapas de Israel en el desierto', 'El sustantivo מַסָּע (massaʿ) deriva del verbo נסע (''arrancar estacas, ponerse en marcha'') y designa el acto de levantar campamento y proseguir el viaje, o más específicamente, una etapa individual dentro de una marcha más larga. Aparece casi exclusivamente en las narraciones del Pentateuco sobre la travesía por el desierto, donde traza el movimiento de Israel de un campamento al siguiente. Génesis 13:3 lo emplea para el regreso escalonado de Abram desde Egipto hasta Betel. Números 10:12 marca la partida del Sinaí ''por sus jornadas,'' y Números 33:1-2 cataloga las cuarenta y dos ''etapas'' de la travesía de Israel por el desierto como un itinerario sagrado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4553', 'spa', 'Lamento, lamentación; llanto comunal intenso por los muertos, por calamidad o en aflicción penitencial.', 'Lamento, lamentación; llanto comunal intenso por los muertos, por calamidad o en aflicción penitencial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4554', 'spa', 'forraje, pienso -- alimento para animales compuesto de grano mezclado con paja', 'Término directo para el alimento animal o forraje, que aparece exclusivamente en narraciones de hospitalidad donde los asnos y camellos de los viajeros deben ser provistos junto a sus dueños. Al siervo de Abraham se le ofrece ''paja y forraje'' para sus camellos (Gn 24:25, 32), los hermanos de José alimentan a sus asnos en la posada egipcia (Gn 42:27; 43:24), y el anciano de Guibeá provee forraje para los asnos del levita (Jue 19:19). En todos los casos, ofrecer forraje es señal de hospitalidad generosa. El español ''forraje'' y el alemán ''Futter'' captan el mismo sentido agrícola.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4556', 'spa', 'Erupción escamosa o costra en la piel, especialmente en el contexto de pureza ritual', 'Este término aparece exclusivamente en Levítico 13 como parte del sistema sacerdotal de diagnóstico de afecciones cutáneas. Designa una costra o erupción escamosa sobre la piel que debía ser examinada por el sacerdote. La extensión o curación de dicha condición determinaba si la persona permanecía ritualmente limpia o impura. La evidencia multilingüe confirma que se refiere a la costra secundaria que se forma sobre una herida o lesión en proceso de cicatrización.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4557', 'spa', 'Número, cuenta, total; la cantidad de personas o cosas, a veces idiomáticamente «escasez», y una vez «relato».', 'Mispár es el sustantivo hebreo principal para una cantidad contada: el «número de» algo. Derivado de la raíz s-p-r («contar, relatar»), aparece abrumadoramente en cadenas constructas: «el número de los hijos de Israel» (Gn 34:30), «el número de los días» (Lv 25:15), «el número de las estrellas» (Sal 147:4). La expresión en mispár («sin número», «innumerable») es un modismo estándar para la abundancia incontable (Gn 41:49; Jue 6:5). La evidencia multilingüe es directa — español número, francés nombre, alemán Zahl — porque contar es una actividad humana universal. Pero dos sentidos periféricos merecen atención: el idiomático meté mispár («hombres de número», es decir, «pocos hombres»), donde la palabra paradójicamente transmite escasez, y una aparición aislada en Jueces 7:15 donde mispár puede significar «relato» de un sueño, conservando el sentido narrativo de la raíz verbal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4565', 'spa', 'Escondite, lugar secreto — sitio oculto para refugio, emboscada o misterio divino', 'Este sustantivo, derivado de la raíz s-t-r (''esconder, ocultar''), designa un lugar secreto o encubierto, con connotaciones tanto siniestras como salvíficas según el contexto. En los Salmos describe los escondrijos de los malvados que acechan al inocente como un león agazapado al acecho (Sal 10:8-9; 17:12; 64:4). Jeremías lo emplea para los lugares ocultos donde el pueblo de Dios llora en secreto (13:17) y los refugios escondidos que no escapan al escrutinio divino (23:24; 49:10). Isaías habla de ''tesoros de lugares secretos'' que Dios revela a Ciro (45:3). Habacuc lo aplica a imágenes cósmicas del ocultamiento divino (3:14). La palabra abarca así un espectro notable — desde la emboscada del criminal hasta el misterioso ocultamiento de Dios mismo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4569a', 'spa', 'Lugar de cruce: vado de un río, paso de montaña, o la acción de atravesar', 'Este término geográfico y táctico describe lugares donde es posible o estratégico cruzar. Puede referirse a un vado poco profundo como el cruce del Jaboc (Gn 32), a un paso de montaña como la posición estratégica de Micmas (1 S 13), o incluso al movimiento de una vara (Is 30). La raíz hebrea implica movimiento a través de una barrera. En cada contexto se subraya la vulnerabilidad o importancia estratégica: los ríos deben ser vadeados, los pasos controlados y la disciplina administrada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4569b', 'spa', 'Vado, paso de montaña o pasaje — un punto de cruce en el terreno, ya sea a través de agua o un desfiladero estrecho', 'Sustantivo femenino que designa un lugar por donde se cruza, ya sea un vado poco profundo en un río o un paso angosto de montaña. Aparece sobre todo en contextos militares: los vados del Jordán que los hombres de Ehúd tomaron para cortar la retirada a los moabitas (Jue 3:28), los cruces disputados en tiempos de Jefté (Jue 12:5-6, el célebre episodio del ''shibolet''), y los desfiladeros rocosos que flanqueaban el audaz asalto de Jonatán en Micmas (1 S 14:4). Isaías lo emplea tanto para un paso montañoso que atraviesa el ejército asirio (Is 10:29) como para los pasajes fluviales de Babilonia que fueron vulnerados (reflejado en Jer 51:32).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4570', 'spa', 'Surco, senda o rodada de carro; en sentido figurado, el curso de la vida o la conducta de una persona; también un campamento militar circular formado ', 'Surco, senda o rodada de carro; en sentido figurado, el curso de la vida o la conducta de una persona; también un campamento militar circular formado por carros. Derivado de una raíz que sugiere redondez o rodadura, este sustantivo presenta dos sentidos bastante distintos según el contexto. En los Salmos y Proverbios designa los surcos o sendas trilladas que siguen los viajeros, y se convierte en una poderosa metáfora de la dirección moral de la vida — las ''sendas de justicia'' (Sal 23:3) o los caminos torcidos de los malvados (Pr 2:15; Is 59:8). En las narraciones de David, sin embargo, se refiere a la barricada circular de carros que formaba el campamento de Saúl (1 S 17:20; 26:5-7), una formación militar concreta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4571', 'spa', 'Resbalar, deslizar, vacilar; en causativo, hacer temblar o tambalear — de pies que pierden estabilidad o juicio divino que causa temblor.', 'Verbo que describe la pérdida de pie firme, tanto en sentido literal como figurado. En salmos de confianza, los fieles declaran que sus pies no resbalan porque Dios ensancha su camino (2 S 22:37; Sal 18:36; 26:1), mientras Job observa que los que tropiezan son despreciados por quienes viven a sus anchas (Job 12:5). El Hifil causativo aparece en oración imprecatoria, pidiendo a Dios que haga tambalear continuamente los lomos de los enemigos (Sal 69:23). La imagen central es la del suelo que cede bajo los pies.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4574', 'spa', 'manjares, delicias, alimentos exquisitos', 'Alimentos refinados o lujosos, especialmente los servidos en contextos reales o disfrutados por los acomodados. El término aparece en la bendición de Jacob sobre Aser: «su pan será sustancioso, y él dará manjares de rey» (Génesis 49:20). En Lamentaciones se describe la inversión de fortunas: quienes antes comían «delicadamente» ahora perecen en las calles (Lamentaciones 4:5). Proverbios promete que disciplinar al hijo «dará deleite a tu alma» (Proverbios 29:17). El vocablo abarca desde el alimento exquisito hasta un modo de vida delicado asociado a la prosperidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4578', 'spa', 'Organos internos, entranas (fisico); sede de emociones profundas y compasion; vientre o entranas como fuente de descendencia.', 'Organos internos, entranas (fisico); sede de emociones profundas y compasion; vientre o entranas como fuente de descendencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4581', 'spa', 'Fortaleza, baluarte; refugio o lugar de seguridad (frecuentemente referido a Dios); fuerza o poder protector como cualidad abstracta.', 'Fortaleza, baluarte; refugio o lugar de seguridad (frecuentemente referido a Dios); fuerza o poder protector como cualidad abstracta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4583', 'spa', 'Habitación o morada, especialmente de Dios; guarida o cubil de animales salvajes; refugio o amparo', 'Habitación o morada, especialmente de Dios; guarida o cubil de animales salvajes; refugio o amparo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4584', 'spa', 'Maón — ciudad en la serranía de Judá y su desierto circundante; también nombre de clan', 'Nombre propio que identifica un asentamiento en las tierras altas de Judá, a unos trece kilómetros al sur de Hebrón, incluido entre las ciudades de la serranía de Judá (Jos 15:55). El desierto circundante de Maón sirvió de refugio a David durante la persecución de Saúl (1 S 23:24-25), y el acaudalado Nabal apacentaba allí sus rebaños (1 S 25:2). En Jueces 10:12 el nombre aparece entre los antiguos opresores de Israel, probablemente vinculado a los meunitas. La noticia genealógica de 1 Crónicas 2:45 sitúa a Maón entre los descendientes de Caleb, reflejando el asentamiento calebita en esta región.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4585', 'spa', 'Guarida de animales salvajes; morada o refugio, especialmente de Dios como amparo para su pueblo', 'Derivado de una raíz que significa ''habitar,'' este sustantivo femenino abarca tanto las guaridas de animales como las moradas humanas o divinas. En su uso más frecuente describe las madrigueras donde leones y fieras se refugian — el cachorro de león rugiendo desde su guarida (Am 3:4), las criaturas regresando a sus cubiles al amanecer (Sal 104:22) y las poéticas guaridas de leones en el Líbano (Cnt 4:8). Sin embargo, la palabra alcanza su cima teológica en Deuteronomio 33:27, donde Moisés declara que el Dios eterno mismo es una meʿonah — un refugio y morada para su pueblo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4586', 'spa', 'Meunim/meunitas: grupo étnico al sur o sureste de Canaán, enemigos de Judá y posteriormente sirvientes del templo.', 'Nombre propio gentilicio que identifica a los meunim o meunitas, un pueblo situado al sur o sureste de Canaán, posiblemente vinculado con la ciudad de Maón en Edom. Aparecen como enemigos derrotados por los simeonitas en tiempos de Ezequías (1 Cr 4:41), como adversarios sometidos por el rey Uzías (2 Cr 26:7) y, en una transformación notable, como sirvientes del templo (netineos) que regresaron del exilio con Zorobabel (Esd 2:50; Neh 7:52). La forma Minaioi de la Septuaginta podría vincularlos con los mineos del sur de Arabia, aunque esta identificación sigue siendo debatida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4591', 'spa', 'Ser o hacerse pocos, disminuir; en Hifil: hacer pocos, reducir, dar menos; ser demasiado pequeño o insignificante', 'Ser o hacerse pocos, disminuir; en Hifil: hacer pocos, reducir, dar menos; ser demasiado pequeño o insignificante');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4592', 'spa', 'Un poco, pocos, cantidad pequeña; casi, por poco; pronto, en un instante; poco a poco, gradualmente.', 'Sustantivo que expresa pequeñez en cantidad, número, tiempo o grado. En su uso más básico significa «un poco» de algo: un poco de agua (Gn 18:4), un poco de comida (Gn 43:2). Referido a personas, significa «pocos» (Dt 7:7: «erais los menos de todos los pueblos»). En la construcción idiomática ki-me''at se convierte en el adverbio «casi» o «por poco», mientras que los usos temporales producen «pronto» o «en un instante». La flexibilidad de la palabra le permite funcionar como adjetivo, sustantivo o adverbio, y su fuerza retórica en la construcción ha-me''at («¿es poca cosa?») la convierte en instrumento del desafío profético.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4598', 'spa', 'Manto, túnica exterior; prenda que se vestía sobre la túnica, asociada a personas de rango, sacerdotes y profetas', 'Manto, túnica exterior; prenda que se vestía sobre la túnica, asociada a personas de rango, sacerdotes y profetas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4599', 'spa', 'Manantial o fuente de agua; en sentido figurado, fuente de vida, vitalidad o bendición', 'Manantial o fuente de agua; en sentido figurado, fuente de vida, vitalidad o bendición');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4600', 'spa', 'Apretar, estrujar o clavar con fuerza, a menudo con connotaciones violentas o sexuales', 'Este verbo describe la presión física intensa aplicada sobre objetos o cuerpos. Sus tres apariciones abarcan desde lo cúltico (animales emasculados no aptos para el sacrificio en Lv 22), hasta lo marcial (la lanza de Saúl clavada en el suelo en 1 S 26), pasando por lo violentamente sexual (la metáfora gráfica de Ezequiel sobre el abuso de Egipto contra Jerusalén y Samaria en Ez 23). El elemento constante es la compresión o penetración forzada, ya sea estrujando, aplastando o clavando.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4601', 'spa', 'Maaca — nombre propio llevado por varios hombres, mujeres y un pequeño territorio arameo cerca del Hermón', 'Maaca — nombre propio llevado por varios hombres, mujeres y un pequeño territorio arameo cerca del Hermón');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4602', 'spa', 'Maacateo — adjetivo gentilicio que designa a alguien del territorio arameo de Maacá', 'Adjetivo gentilicio (demónimo) que identifica a una persona como nativa o habitante de Maacá, un pequeño reino arameo al pie del monte Hermón, cerca del Golán. En su uso colectivo, describe a la población maacatea no conquistada que permaneció dentro de las fronteras de Israel (Dt 3:14; Jos 12:5; 13:11, 13). También identifica a individuos específicos: uno de los guerreros de David (2 S 23:34), Estemoa en la genealogía de Judá (1 Cr 4:19) y Jaazanías, quien se unió a Gedalías tras la caída de Jerusalén (2 R 25:23; Jer 40:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4603', 'spa', 'Actuar infielmente, cometer traicion: quebrantamiento del pacto contra Dios mediante sacrilegio o deslealtad.', 'Actuar infielmente, cometer traicion: quebrantamiento del pacto contra Dios mediante sacrilegio o deslealtad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4604', 'spa', 'Infidelidad, transgresión sacra; acto de traición contra el pacto con Dios, frecuente en contextos cultuales', 'Infidelidad, transgresión sacra; acto de traición contra el pacto con Dios, frecuente en contextos cultuales');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4605', 'spa', 'Arriba, hacia arriba — en frases adverbiales y preposicionales para extensión aditiva (''y arriba''), origen desde lo alto, dirección ascendente y posición estática encima.', 'Este sustantivo convertido en adverbio aparece solo en frases fijas pero cubre un rico espectro espacial. Su uso más frecuente (~57x) es la fórmula censal «de veinte años y arriba» (Nm 1:3), donde marca una extensión abierta más allá de un umbral. Como compuesto preposicional mim-ma''al puede indicar procedencia desde lo alto (Gn 6:16; Éx 25:21) o posición estática encima de algo (Gn 22:9: Abraham colocó a Isaac sobre la leña «encima»). En contextos direccionales, le-ma''lá significa «hacia arriba, más alto» (Dt 28:43; 1 Cr 14:2). La expresión «los cielos de arriba» (Dt 4:39) se convirtió en fórmula teológica para la trascendencia de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4608', 'spa', 'Subida; pendiente geográfica, camino de montaña o paso; también escaleras o peldaños de una estructura arquitectónica', 'Subida; pendiente geográfica, camino de montaña o paso; también escaleras o peldaños de una estructura arquitectónica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4609b', 'spa', 'Escalón, escalera; ascenso; título salmódico ''Cántico de los Ascensos'' para los salmos de peregrinación (Sal 120-134); piso superior.', 'Escalón, escalera; ascenso; título salmódico ''Cántico de los Ascensos'' para los salmos de peregrinación (Sal 120-134); piso superior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4610', 'spa', 'Subida, cuesta; una elevación geográfica o camino ascendente, frecuentemente parte de topónimos como el Paso de Acrabim.', 'Sustantivo masculino que designa un camino ascendente, paso de montaña o cuesta empinada. Aparece con frecuencia como elemento constructo en topónimos propios, sobre todo «la subida de Acrabim» (Paso de los Escorpiones), que marca el límite meridional de Canaán (Nm 34:4; Jos 15:3; Jue 1:36). El mismo vocablo describe la subida hacia pueblos y ciudades en contextos narrativos. Tanto el sentido de sustantivo común como el elemento incorporado en nombres propios se preservan en las traducciones: el hindi translitéra «Akrabbim» mientras que el español y el inglés traducen el rasgo geográfico como «subida» o «ascent».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4611', 'spa', 'Obras, practicas: acciones habituales o conducta, generalmente evaluada moralmente como mala o (raramente) buena.', 'Obras, practicas: acciones habituales o conducta, generalmente evaluada moralmente como mala o (raramente) buena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4612', 'spa', 'puesto, cargo, oficio; posición asignada de servicio o asistencia', 'Derivado de la raíz ''estar de pie,'' este sustantivo designa la posición asignada donde alguien cumple su deber, ya sea un puesto sacerdotal, la estación de un asistente de la corte o un cargo oficial. Cuando la reina de Sabá observó ''la disposición de los siervos de Salomón'' (1 R 10:5; 2 Cr 9:4), quedó maravillada ante su servicio disciplinado a la mesa. Los levitas permanecieron ''en sus puestos'' durante la Pascua de Josías (2 Cr 35:15), e Isaías advierte a Sebna que Dios lo arrancará ''de tu puesto'' (Is 22:19). El español ''posición'' y ''puesto'' reflejan tanto la dimensión física como la institucional de esta palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4615', 'spa', 'profundidades, abismos -- las honduras literales del oceano o las profundidades figuradas de la angustia y el sufrimiento', 'Siempre en plural, este sustantivo evoca profundidades abrumadoras, ya sea el fondo literal del mar o el abismo figurado del sufrimiento humano. El salmista clama ''De lo profundo te invoco, oh SENOR'' (Sal 130:1), una de las lineas iniciales mas queridas de toda la Escritura. En otros pasajes, las aguas amenazan con sumergir: ''Me hundo en cieno profundo donde no hay pie; he llegado a aguas profundas'' (Sal 69:2, 14). El poder soberano de Dios seco ''las profundidades del mar'' para el exodo de Israel (Is 51:10), y el imperio comercial de Tiro se hundio ''en las profundidades de las aguas'' (Ez 27:34).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4616', 'spa', 'A fin de que, por causa de; preposición-conjunción que expresa propósito, causa o el beneficiario de una acción.', 'Palabra funcional notablemente versátil, lema''an tiende un puente entre el propósito y la causa de maneras que mantienen alertas a los traductores. Cuando Dios dice que endureció el corazón de Faraón «lema''an mostrar estas señales» (Éx 10:1), el sentido es claramente final: «a fin de que». Pero cuando Abraham intercede «por causa de cincuenta justos» (Gn 18:24), la misma palabra expresa beneficiario-causa: «por causa de, en consideración a». Muchas apariciones se sitúan en la frontera entre ambas lecturas, especialmente en oráculos proféticos. El francés distingue afin que (propósito) frente a à cause de (causa), y el alemán damit frente a um...willen, mostrando cómo las lenguas europeas escinden lo que el hebreo unifica en una sola partícula.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4617', 'spa', 'Respuesta, réplica; propósito, intención', 'El sustantivo מַעֲנֶה (ma''aneh), de la raíz עָנָה (''responder''), designa una respuesta o réplica verbal: el contenido de lo que se dice en retorno. Proverbios atesora esta palabra: ''la blanda respuesta quita la ira'' (Pr 15:1), y ''¡la palabra a su tiempo, cuán buena es!'' (Pr 15:23). En Job 32, el joven Elihú espera la respuesta de los amigos que nunca llega (32:3, 5), y habla porque el silencio de ellos no ha dejado réplica alguna. Una sola aparición en Proverbios 16:4 extiende el sentido hacia ''propósito'' o ''intención'' — ''todo lo hizo Jehová para su propósito'' — donde la idea de ''respuesta'' se convierte en la correspondencia inscrita en el diseño de la creación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4618', 'spa', 'Surco o caballón en la tierra arada, trazado por el paso del arado', 'Este término agrícola aparece en contextos que describen las hendiduras trazadas por el arado en el suelo. Las apariciones bíblicas se refieren a surcos literales en los campos. El uso más vívido se encuentra en el Salmo 129, donde los opresores «araron sobre la espalda» de Israel haciendo largos surcos, una metáfora del sufrimiento prolongado. El contexto del campo de batalla en 1 Samuel 14 y la imaginería paralela del Salmo 129 confirman esta referencia agrícola fundamental.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4627', 'spa', 'Mercancía, bienes comerciales; artículos intercambiados en el comercio, usado exclusivamente de Tiro en Ezequiel 27.', 'Este sustantivo masculino designa mercancía o bienes comerciales, derivado de la raíz ''arav que significa ''intercambiar'' o ''dar en prenda''. Sus nueve apariciones se concentran en un solo capítulo: Ezequiel 27, el lamento profético sobre el imperio comercial de Tiro. El capítulo cataloga la asombrosa variedad de las redes mercantiles de Tiro: Tarsis traía plata y hierro como mercancía (vv. 12-13), Judá comerciaba con trigo y miel (v. 17), y Arabia intercambiaba corderos y cabras (v. 21). El estribillo repetido ''tu mercancía'' construye hacia el vuelco dramático de los versículos 27 y 34, donde todas las mercancías de Tiro se hunden en el corazón de los mares.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4628', 'spa', 'Oeste; punto cardinal donde se pone el sol, usado en orientación geográfica y descripciones territoriales.', 'Oeste; punto cardinal donde se pone el sol, usado en orientación geográfica y descripciones territoriales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4631', 'spa', 'Cueva, caverna: camara natural de roca usada como refugio, sepultura, escondite o guarida de fieras y ladrones.', 'Cueva, caverna: camara natural de roca usada como refugio, sepultura, escondite o guarida de fieras y ladrones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4634', 'spa', 'Línea de batalla o formación militar; también una hilera o disposición ordenada de objetos', 'Línea de batalla o formación militar; también una hilera o disposición ordenada de objetos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4635', 'spa', 'Hilera, disposición; la exhibición ordenada de los panes de la proposición en el tabernáculo o templo, en hileras rituales ante el SEÑOR.', 'Término técnico cúltico para las hileras ordenadas de pan dispuestas ante la presencia de Dios en el santuario. El ''pan de la disposición'' (lechem ha-ma''arekhet) era una obligación ritual semanal: doce panes en dos hileras de seis sobre la mesa de oro (Lv 24:5-7). Crónicas y Nehemías emplean el término para el servicio del templo restaurado tras el exilio. El español distingue entre ''la disposición'' (el sistema ritual en su conjunto) y ''la hilera'' (la fila física concreta), reflejando los dos énfasis semánticos de la palabra hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4639', 'spa', 'Obra, labor, artesanía; abarca el trabajo artesanal, la actividad productiva, la conducta humana, los actos divinos y el rendimiento agrícola', 'מַעֲשֶׂה deriva de la raíz עָשָׂה (''hacer, fabricar'') y cubre todo el espectro desde la creación divina hasta la artesanía humana y la conducta moral. Las instrucciones del tabernáculo están saturadas de este término: cada cortina tejida, cada candelabro labrado y cada pantalla bordada se describe como מַעֲשֶׂה (Éx 26-28). Sin embargo, la misma palabra condena la maldad humana cuando Esdras confiesa ''nuestros malos מַעֲשִׂים'' (Esd 9:13). Su amplitud revela una cultura que percibía continuidad entre fabricar cosas y obrar: toda actividad humana con propósito bajo un mismo concepto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4641', 'spa', 'Maaseías — ''obra de Yah,'' nombre teofórico llevado por numerosos sacerdotes, levitas y funcionarios', 'Maaseías — ''obra de Yah,'' nombre teofórico llevado por numerosos sacerdotes, levitas y funcionarios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4643', 'spa', 'Diezmo o decima parte; un decimo sagrado del producto entregado a Dios o a los levitas, o simplemente una fraccion numerica.', 'Diezmo o decima parte; un decimo sagrado del producto entregado a Dios o a los levitas, o simplemente una fraccion numerica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4648', 'spa', 'Mefiboset (Merib-baal) — hijo de Jonatán y nieto de Saúl, cojo de ambos pies, a quien David mostró lealtad.', 'Mefiboset (Merib-baal) — hijo de Jonatán y nieto de Saúl, cojo de ambos pies, a quien David mostró lealtad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4656', 'spa', 'cosa horrenda o abominable (ídolo)', 'Término que designa algo espantoso u horripilante, empleado específicamente para describir un ídolo abominable que la madre del rey Asá, Maaca, fabricó para el culto a Asera (1 Reyes 15:13; 2 Crónicas 15:16). La reforma de Asá incluyó derribar y quemar esta «cosa horrible», demostrando su firme determinación de erradicar la idolatría aun cuando ello significaba enfrentar la apostasía de su propia madre. La palabra transmite no solo un rechazo moral, sino una repulsión visceral: algo que hace estremecer a quien lo contempla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4658', 'spa', 'Caída, ruina, derrocamiento; cadáver o cuerpo abatido', 'El sustantivo מַפֶּלֶת deriva de la raíz נפל (''caer'') y designa el resultado de una caída catastrófica. En los oráculos de Ezequiel contra Tiro y Egipto, funciona como término clave profético para el derrocamiento político y la ruina nacional: ''al estruendo de tu caída'' (Ez 26:15). La palabra posee una fisicidad visceral: las naciones tiemblan, las costas se estremecen, los ejércitos se desploman. Sin embargo, en su única aparición concreta, significa algo marcadamente distinto: el cadáver del león que Sansón había matado (Jue 14:8), donde las traducciones en español e inglés confirman un cuerpo muerto y no un colapso abstracto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4662', 'spa', 'censo, revista militar, nombramiento, lugar designado', 'Término relacionado con contar, nombrar o designar, con aplicaciones tanto en censos militares como en designaciones sagradas. Aparece en los relatos paralelos del censo de David (2 Samuel 24:9; 1 Crónicas 21:5), registrando la revista militar de Israel. Describe también el nombramiento administrativo que Ezequías hizo de levitas para el servicio del templo (2 Crónicas 31:13). En la visión del templo de Ezequiel, designa un lugar señalado dentro del recinto sagrado para disponer de los restos del sacrificio por el pecado (Ezequiel 43:21).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4670', 'spa', 'Umbral — la piedra o madero en la base de una puerta, especialmente de un templo o entrada sagrada', 'Sustantivo masculino que designa el umbral de un edificio, la viga horizontal o losa de piedra en la parte inferior de una puerta sobre la cual se pisa al entrar. Casi todas sus apariciones revisten peso sacral. En la narración de Dagón, los fragmentos del ídolo yacen sobre el umbral de su templo, por lo que los sacerdotes evitan pisarlo desde entonces (1 S 5:4-5). En el templo visionario de Ezequiel, el umbral ocupa un lugar prominente: la gloria de YHWH se desplaza hacia el umbral (Ez 9:3; 10:4, 18) y las aguas sanadoras brotan de debajo de él (Ez 47:1). Sofonías condena a quienes saltan sobre el umbral en un rito pagano (Sof 1:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4671', 'spa', 'Tamo — las cáscaras ligeras del grano trillado, usado figuradamente para lo que carece de valor y el viento se lleva', 'Sustantivo masculino que designa el tamo, las cáscaras secas y la paja quebrada que se separan del grano durante la trilla. En todas sus apariciones bíblicas figura en un símil introducido por la preposición כְּ (''como''), siempre arrastrado por el viento, pintando una imagen vívida de lo efímero y lo sin valor. Los impíos son ''como el tamo que arrebata el viento'' (Sal 1:4), las naciones hostiles se dispersan ''como tamo en los montes'' ante la reprensión de Dios (Is 17:13), y un día entero puede pasar ''como tamo'' (Sof 2:2). Es una de las metáforas más memorables de la Biblia sobre el juicio divino que barre a los impíos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4672', 'spa', 'Hallar, descubrir, encontrar; Nifal: ser hallado, estar presente; Hifil: entregar, presentar; raro: bastar, ser suficiente', 'Uno de los verbos más frecuentes de la Biblia hebrea, מָצָא abarca desde la búsqueda deliberada hasta el encuentro inesperado. En Qal va desde hallar una asna perdida (1 S 9:4) hasta hallar gracia ante los ojos de alguien, expresión formulaica (מָצָא חֵן) que aparece más de 40 veces. El Nifal pasivo produce la fórmula distintiva de Crónicas para ''todos los que se hallaron presentes'', mientras que el raro Hifil causativo significa entregar o presentar. Una acepción menor sorprendente, ''bastar'' (Nm 11:22), refleja la lógica de que lo hallado es lo disponible y, por tanto, lo suficiente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4673', 'spa', 'Guarnición o puesto militar; lugar de estacionamiento o posición asignada', 'Derivado de la raíz natsav (''estar de pie, tomar posición''), este sustantivo masculino designa una guarnición militar o un lugar donde alguien permanece en una posición asignada. Su sentido militar domina la narrativa del enfrentamiento de Saúl y Jonatán con los filisteos, donde el término aparece siete veces para la guarnición filistea en el paso de Micmas (1 S 13-14). En su sentido no militar, Josué 4 lo emplea para el punto exacto en el lecho del Jordán donde se plantaron los pies de los sacerdotes que llevaban el arca. Isaías 22:19 lo aplica metafóricamente al cargo u oficio de Sebna, del cual Dios lo destituirá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4676', 'spa', 'Piedra erguida o pilar; una piedra vertical erigida como monumento conmemorativo o como objeto de culto pagano destinado a ser destruido.', 'Piedra erguida o pilar; una piedra vertical erigida como monumento conmemorativo o como objeto de culto pagano destinado a ser destruido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4678', 'spa', 'Pilar o piedra erguida como memorial o marcador sagrado; también el tocón o tronco remanente de un árbol talado', 'Sustantivo femenino derivado de la raíz que significa ''estar de pie'', que abarca dos referentes bastante distintos. Como pilar o piedra erguida, marca memoriales: Jacob unge un pilar en Betel (Gen 35:14) y Absalón levanta su monumento en el Valle del Rey (2 Sam 18:18). Como tocón, aparece en la parábola de juicio de Isaías: aun después de que la tierra santa es quemada, queda un tronco como semilla de esperanza (Isa 6:13). La divergencia es marcada entre las traducciones: el español distingue ''estela/pilar'' de ''tronco'', evidencia de que los dos sentidos se percibían claramente como distintos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4679', 'spa', 'Fortaleza montañosa o refugio defensivo en terreno rocoso e inaccesible, usado como resguardo militar o de supervivencia.', 'Se refiere a un lugar fortificado de refugio, generalmente situado en terreno montañoso y escarpado. Durante el periodo de los Jueces, los israelitas se escondían de las incursiones madianitas en estas fortalezas montañosas (Jue 6:2), y David se refugió célebremente de Saúl en las fortalezas del desierto de Judá (1 Sam 23:14, 29). La construcción con «peñas» (Is 33:16) resalta la naturaleza rocosa y agreste de estos refugios. El término también designa la ciudadela jebusea que David capturó y convirtió en su capital (1 Cr 11:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4680', 'spa', 'Escurrir o exprimir (extrayendo líquido activamente); en Nifal pasivo, ser escurrido o exprimido hasta secar', 'Verbo de extracción de líquido. מָצָה describe la acción enérgica de exprimir o escurrir el fluido de un recipiente o material. Gedeón exprime el rocío del vellón (Jue 6:38); a Jerusalén se le dice que ha apurado la copa de la furia de Dios hasta las heces (Is 51:17); los impíos apuran las heces de la copa del juicio (Sal 75:8). En el Nifal pasivo, la sangre del sacrificio ''será exprimida'' al pie del altar (Lv 1:15; 5:9). El español distingue la acción activa de exprimir (''exprimiste'') de la pasiva (''será exprimido''), mientras que cognados árabes como imtassa (absorber, succionar) refuerzan la imagen central de una extracción exhaustiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4682', 'spa', 'Pan ácimo o tortas sin levadura, preparados sin fermento para la Pascua, las ofrendas sacrificiales y la hospitalidad urgente.', 'Pan ácimo o tortas sin levadura, preparados sin fermento para la Pascua, las ofrendas sacrificiales y la hospitalidad urgente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4683', 'spa', 'Contienda, discordia o riña entre personas o grupos', 'Este sustantivo designa el conflicto que surge del orgullo, la codicia o la malicia. Aparece en la literatura sapiencial advirtiendo sobre las fuentes de la discordia (Proverbios lo vincula con la soberbia y la transgresión) y en la denuncia de Isaías contra el ayuno que conduce a peleas en lugar de justicia. El término no alude a un simple desacuerdo sino a una contienda activa, el tipo de riña que quiebra la comunidad. BDB lo distingue del término homónimo que significa «pan sin levadura».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4686a', 'spa', 'red, trampa (para cazar o atrapar)', 'Red o trampa de caza, empleada casi exclusivamente en descripciones figuradas del juicio divino. Dios extiende su red para capturar a Israel en su rebeldía (Ezequiel 12:13; 17:20), imagen de un juicio ineludible. El salmista describe la aflicción como ser llevado «a la red» (Salmo 66:11). Ezequiel también condena a las falsas profetisas que cazan almas con sus encantamientos, amenazando con arrancar al pueblo de Dios de sus «redes» (Ezequiel 13:21). La imagen enfatiza el entrampamiento: la víctima atrapada sin posibilidad de escape.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4686b', 'spa', 'Fortaleza, plaza fuerte; también (homónimo) red o trampa — lugar de refugio defensivo, o instrumento de caza', 'Fortaleza, plaza fuerte; también (homónimo) red o trampa — lugar de refugio defensivo, o instrumento de caza');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4687', 'spa', 'Mandamiento, precepto, directiva; instrucción vinculante de Dios como ley del pacto o de una autoridad humana como decreto ejecutivo', 'מִצְוָה es la palabra por excelencia para el mandamiento divino en la Biblia hebrea, con presencia abrumadora en Deuteronomio y los Salmos como las estipulaciones que Dios da a Israel para cumplir. ''El mandamiento es lámpara y la Torá es luz'' (Pr 6:23) capta su carácter vivificante. Ya sea en singular — refiriéndose al cuerpo entero de la ley del pacto — o en plural — enumerando preceptos específicos —, מִצְוָה enmarca la obediencia como respuesta agradecida de Israel a la liberación divina. Un uso menor pero distinguible aplica el término a directivas reales o sacerdotales: el mandato del rey (2 Cr 24:21) o una orden administrativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4688', 'spa', 'Profundidad, abismo — las insondables profundidades oceánicas, referidas al Mar Rojo, aguas caóticas y el poder divino de sumergir.', 'El sustantivo מְצוּלָה (metsulah) designa una profundidad acuática o abismo. En el Cántico del Mar, las fuerzas del faraón se hunden «en las profundidades como piedra» (Éx 15:5; Neh 9:11). Los Salmos lo emplean para expresar angustia abrumadora: el suplicante clama desde «aguas profundas» (Sal 69:2, 15; 88:6), y los marineros contemplan maravillas en lo profundo (Sal 107:24). Jonás ora desde la metsulah que lo envolvió (Jon 2:3). Dios promete arrojar los pecados de Israel a las profundidades del mar (Miq 7:19). Leviatán hace hervir el abismo como una olla (Job 41:31).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4689', 'spa', 'Angustia, aflicción, estrechez: estado de penuria severa o constricción, frecuentemente durante un asedio o prueba', 'Sustantivo masculino que denota una condición de constricción severa, angustia o aflicción. Su raíz (צ-ו-ק, ''apretar, constreñir'') evoca una opresión física trasladada a la extremidad emocional y existencial. En Deuteronomio 28:53, 55, 57 describe las condiciones espantosas durante un asedio, donde el hambre empuja a actos impensables. En 1 Samuel 22:2, todo hombre ''en estrechez'' se reúne con David en la cueva de Adulam. En el Salmo 119:143 el salmista confiesa que ''la angustia y la aflicción me han alcanzado''. La palabra apunta consistentemente a estar acorralado sin escapatoria fácil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4691', 'spa', 'Angustia, aflicción o aprieto extremo — estado de estar cercado por la adversidad sin salida visible', 'Sustantivo femenino que denota angustia profunda, aflicción o la condición de hallarse en un aprieto extremo. A menudo aparece emparejado con צָרָה (''tribulación'') para intensificar el cuadro de sufrimiento, como en el estremecedor catálogo del Día de YHWH en Sofonías 1:15: ''día de tribulación y de angustia''. Sus apariciones más memorables se encuentran en el Salmo 107, el gran salmo de acción de gracias, donde cuatro veces Dios libra al pueblo ''de sus angustias'' (vv. 6, 13, 19, 28). Cada idioma busca expresar esa misma sensación visceral de estar oprimido más allá de toda resistencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4692', 'spa', 'Asedio o estado de sitio; también fortaleza o plaza fuerte fortificada', 'Asedio o estado de sitio; también fortaleza o plaza fuerte fortificada');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4693', 'spa', 'Matsor — nombre poético de Egipto que enfatiza sus fortificaciones o fronteras', 'Este término hebreo aparece exclusivamente en contextos poéticos como un nombre alternativo para Egipto. La palabra probablemente deriva de la raíz que significa ''asedio'' o ''fortaleza'', destacando las fronteras fortificadas o la fuerza defensiva de Egipto. Se encuentra en oráculos proféticos sobre los cursos de agua de Egipto y en la visión de Miqueas sobre la restauración futura, donde los fieles vendrán de ''las ciudades de Matsor''. La evidencia multilingüe refleja la doble naturaleza de este término: tanto como nombre propio como evocación del concepto de fortificación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4694', 'spa', 'Fortaleza, fortificación, baluarte — plaza fuerte defensiva u obra de asedio, frecuente en la frase ''ciudades fortificadas''', 'Sustantivo femenino que designa una fortificación, baluarte u obra de asedio: una instalación militar defensiva. Aparece con mayor frecuencia en Crónicas al describir el programa de fortificación de Roboam, quien reforzó ciudades en Judá y Benjamín como ''ciudades fortificadas'' (עָרֵי מְצוּרָה/מְצוּרוֹת, 2 Cr 11:10-11, 23; 12:4; 14:6; 21:3). Nahúm 2:2 ordena ''¡Guarda el baluarte!'' ante la invasión de Nínive, e Isaías 29:3 lo emplea para referirse a las obras de asedio levantadas contra Jerusalén. La palabra abarca ambos lados del cerco: tanto las defensas como las obras construidas para vencerlas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4696', 'spa', 'Frente, ceño — la parte frontal de la cabeza; figuradamente, audacia u obstinación.', 'Frente, ceño — la parte frontal de la cabeza; figuradamente, audacia u obstinación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4700', 'spa', 'Címbalos — instrumentos de percusión metálicos emparejados usados en el culto levítico del templo y en celebraciones.', 'Címbalos — instrumentos de percusión metálicos emparejados usados en el culto levítico del templo y en celebraciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4701', 'spa', 'Turbante, mitra sacerdotal — el turbante de lino enrollado en la cabeza del sumo sacerdote como parte de las vestiduras sagradas.', 'La מִצְנֶפֶת (mitsnephet) es el distintivo turbante de lino usado exclusivamente por el sumo sacerdote, parte de sus vestiduras sagradas descritas en Éxodo y Levítico. Se enrolla alrededor de la cabeza, y sobre él se sujeta con un cordón azul la placa de oro grabada con «Santo a Jehová» (Éx 28:4, 37, 39; 29:6). Moisés lo coloca sobre la cabeza de Aarón en la ceremonia de consagración (Lv 8:9; 16:4). El código visionario del templo de Ezequiel prescribe un turbante para el príncipe o sacerdote (Ez 21:31). La forma emparentada צָנִיף se aplica más ampliamente a cualquier turbante o tocado (Job 29:14; Is 62:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4703', 'spa', 'Paso o pisada, frecuentemente en sentido figurado para referirse al curso o camino de vida de una persona', 'Este término designa el acto físico de pisar o los pasos que uno da, y se emplea con frecuencia en sentido figurado para describir la dirección o trayectoria de la vida. En la literatura sapiencial se dice que Dios establece los pasos del justo (Sal 37), mientras que Proverbios reconoce que los pasos del hombre son dirigidos en última instancia por el Señor. En Daniel aparece en la expresión «a sus pasos», es decir, en su séquito o siguiéndole. La imagen evoca tanto el caminar literal como la trayectoria de las decisiones de cada persona.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4705', 'spa', 'cosa pequena, un poco; pequenez en tamano, numero o duracion', 'Sustantivo que expresa pequenez o insignificancia, ya sea en el tamano de una ciudad, el numero de un grupo o la duracion de un periodo. Lot suplico huir a Zoar, llamandola ''cosa pequena'' (Gn 19:20), y Dios destruyo al ejercito de Juda ''con pocos hombres'' de Aram (2 Cr 24:24). El amigo de Job, Bildad, prometio que aunque su ''comienzo fuera pequeno,'' su final creceria enormemente (Job 8:7). Isaias lamenta que el pueblo de Dios poseyera el lugar santo ''por poco tiempo'' (Is 63:18). El espanol distingue ''pequena'' (tamano) de ''por poco tiempo'' (duracion), revelando la flexibilidad de este vocablo entre los dominios espacial y temporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4708', 'spa', 'Mizpa, topónimo que significa ''atalaya''; varias ciudades israelitas en Judá, Galaad, Moab y Benjamín.', 'Nombre propio de lugar derivado de la raíz tsapah (''vigilar, otear''), que literalmente significa ''atalaya'' o ''puesto de observación''. Varias localidades llevaron este nombre en el antiguo Israel, reflejando la práctica habitual de denominar así los puntos elevados de vigilancia. Las más destacadas incluyen una ciudad en la Sefela de Judá (Jos 15:38), un sitio en Galaad asociado a la campaña de Jefté (Jue 11:29), Mizpa de Moab donde David llevó a sus padres para protegerlos (1 Sam 22:3), y una ciudad benjaminita (Jos 18:26). La recurrencia del nombre en distintas regiones atestigua la frecuencia con que los asentamientos en cumbres servían como atalayas por toda la tierra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4709', 'spa', 'Mizpa (''atalaya''); nombre propio de varios sitios biblicos, especialmente en Benjamin y Galaad.', 'Mizpa (''atalaya''); nombre propio de varios sitios biblicos, especialmente en Benjamin y Galaad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4712', 'spa', 'Estrecheces, angustia o dificultades severas que oprimen por todos lados sin escape', 'Este sustantivo describe una dificultad extrema o angustia, empleando la metáfora espacial de estar encerrado en un lugar estrecho y confinado sin salida. El salmista clama desde «las estrecheces» y halla amplio alivio (Sal 118). El paralelismo con «lazos de la muerte» y el Seol en el Salmo 116 muestra que se trata de un pavor existencial, una crisis que amenaza la vida. Lamentaciones utiliza el plural para describir a Judá conquistada y alcanzada en sus lugares angostos. La imagen es claustrofóbica: estar atrapado, presionado, sin espacio para maniobrar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4713', 'spa', 'Egipcio; adjetivo/sustantivo gentilicio para personas de Egipto (masculino o femenino) y para la tierra de Egipto misma.', 'Egipcio; adjetivo/sustantivo gentilicio para personas de Egipto (masculino o femenino) y para la tierra de Egipto misma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4714', 'spa', 'Egipto (la tierra y la nación); Mizraim (hijo de Cam, antepasado epónimo de los egipcios en la Tabla de las Naciones)', 'מִצְרַיִם aparece más de 630 veces como el nombre hebreo de Egipto, la nación extranjera definitoria en la historia de Israel, desde el descenso de José hasta el Éxodo y los oráculos proféticos. La terminación dual (-áyim) ha sido debatida como posible reflejo del Alto y Bajo Egipto, aunque algunos eruditos la interpretan como forma locativa. En cuatro pasajes de la Tabla de las Naciones (Gn 10:6, 13; 1 Cr 1:8, 11), la misma palabra funciona como nombre propio — Mizraim, hijo de Cam —, donde las traducciones reflejan al antepasado epónimo en lugar del territorio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4717', 'spa', 'Martillos usados para clavar, fijar estacas o dar forma al metal en la construcción y la artesanía', 'Este término para martillos aparece en contextos de construcción y fabricación de ídolos. El templo de Salomón se edificó con tal reverencia que no se oyó ningún martillo en la obra, pues las piedras se labraban previamente (1 Re 6). Isaías y Jeremías emplean el término al describir la fabricación de ídolos: el artesano da forma al metal con martillos y lo asegura con clavos. El martillo representa tanto la habilidad creativa del artesano como, irónicamente, el esfuerzo vano de fabricar dioses con materias primas. Es la herramienta para clavar estacas y modelar materiales resistentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4719', 'spa', 'Maqueda, ciudad real cananea en la Sefela de Judá, conquistada por Josué durante su campaña meridional.', 'Ciudad cananea situada en las tierras bajas de la Sefela de Judá, Maqueda es recordada principalmente por el dramático episodio en que cinco reyes amorreos se escondieron en su cueva durante la persecución de Josué tras la batalla de Gabaón (Jos 10:16-17). Josué selló la cueva, completó la persecución y luego regresó para ejecutar a los reyes y tomar la ciudad (Jos 10:28). Aparece en la lista de reyes derrotados (Jos 12:16) y entre las ciudades asignadas a la tribu de Judá (Jos 15:41). La Septuaginta griega la transcribe como Makeda, y el sitio se identifica tentativamente cerca del actual el-Mughar, al suroeste de Ecrón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4720', 'spa', 'Lugar sagrado o santuario; el espacio consagrado apartado para el culto y la presencia de Dios.', 'Lugar sagrado o santuario; el espacio consagrado apartado para el culto y la presencia de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4723a', 'spa', 'Qué — nombre geográfico de Cilicia en el sureste de Anatolia, fuente de los caballos de Salomón', 'Este nombre propio designa a Qué (también escrito Kue), una región de la antigua Cilicia en lo que hoy es el sureste de Turquía. Aparece exclusivamente en los relatos del comercio internacional de Salomón, específicamente sobre la importación de caballos. La Septuaginta lo transliteraba como ''Thekouë'' o ''Koa'', y la Vulgata como ''Coa''. La erudición moderna identifica este topónimo con la provincia neoasiria de Qué en Cilicia, región famosa por la cría de caballos en el antiguo Cercano Oriente. Las glosas multilingües conservan el prefijo preposicional (''desde Qué''), evidenciando transacciones comerciales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4723b', 'spa', 'esperanza, expectativa -- espera confiada dirigida hacia Dios como fundamento ultimo de la esperanza de Israel', 'Un profundo sustantivo teologico que significa ''esperanza'' o ''fundamento de expectativa,'' usado casi exclusivamente para la esperanza dirigida hacia Dios. En tres de sus cinco apariciones funciona como titulo divino: ''Oh Esperanza de Israel, oh SENOR'' (Jer 14:8; 17:13; 50:7), identificando a Dios mismo como fuente y objeto de la expectativa confiada de Israel. David confeso ante la asamblea que ''nuestros dias sobre la tierra son como sombra, y no hay esperanza'' aparte de Dios (1 Cr 29:15), mientras que Esdras declaro que a pesar de la culpa de Israel, ''aun hay esperanza para Israel'' (Esd 10:2). El termino transmite una confianza firme y orientada hacia el futuro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4723c', 'spa', 'Reunión o acumulación, especialmente de aguas congregadas en un solo lugar', 'Este término del relato de la creación describe las aguas reunidas en un solo lugar, formando mares y permitiendo que la tierra seca aparezca. En Génesis 1, Dios lo usa para la separación del agua y la tierra: a la «reunión de las aguas» la llamó Mares. Las apariciones en Éxodo y Levítico se refieren a depósitos de agua, ya sea en los cauces de Egipto o en una cisterna ritual. El término enfatiza la acumulación en un espacio delimitado: agua congregada en vez de dispersa, recogida en vez de fluir libremente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4725', 'spa', 'Lugar, sitio, localidad; un punto físico, emplazamiento o posición designada; raramente, distancia o espacio medido', 'מָקוֹם es la palabra hebrea cotidiana para ''lugar'', uno de los sustantivos más frecuentes de la Biblia hebrea con más de 400 apariciones. Abarca desde un punto específico donde uno se encuentra (Éx 3:5, ''el lugar donde estás es tierra santa'') hasta localidades con nombre, regiones y posiciones designadas. Las traducciones en todas las lenguas emplean consistentemente su término espacial básico: lugar, lieu, Ort. Una sola aparición en 1 S 26:13, donde David puso distancia entre él y Saúl, muestra un sentido inusual de espacio o distancia medida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4726', 'spa', 'Manantial o fuente; literalmente una fuente de agua, figuradamente el origen de la vida, la sabiduría, la bendición o la purificación; también un fluj', 'Manantial o fuente; literalmente una fuente de agua, figuradamente el origen de la vida, la sabiduría, la bendición o la purificación; también un flujo corporal de sangre');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4731', 'spa', 'Vara, cayado o palo; una rama cortada usada como apoyo para caminar, herramienta de pastor, símbolo de autoridad o arma', 'Vara, cayado o palo; una rama cortada usada como apoyo para caminar, herramienta de pastor, símbolo de autoridad o arma');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4732', 'spa', 'Miclot — nombre personal, líder de clan benjaminita y uno de los oficiales de David', 'Miclot es un nombre personal que aparece en los registros genealógicos y administrativos de Crónicas. El nombre se encuentra en dos contextos distintos: primero, como cabeza de familia benjaminita en la genealogía del clan de Saúl (1 Cr 8-9), y segundo, como oficial en la organización militar de David. La Septuaginta presenta diversas grafías griegas del nombre (Makalōth, Makellōth), aunque omite la referencia en 1 Crónicas 27:4. El significado del nombre probablemente deriva de una raíz relacionada con ''varas'' o ''bastones'', aunque su sentido exacto es incierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4733', 'spa', 'Refugio o asilo; usado exclusivamente en la frase legal ''ciudades de refugio'' para quienes cometieron homicidio involuntario', 'Refugio o asilo; usado exclusivamente en la frase legal ''ciudades de refugio'' para quienes cometieron homicidio involuntario');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4734', 'spa', 'miqlaat — obra tallada, grabado decorativo en la madera y el metal del templo', 'Este sustantivo hebreo designa la talla ornamental o el grabado artístico, y aparece exclusivamente en las descripciones de la construcción del templo de Salomón. El término se refiere al trabajo decorativo en relieve que adornaba los paneles de cedro en el interior del templo y las bases de bronce en el exterior. Sus cuatro apariciones se encuentran en 1 Reyes 6-7, el relato arquitectónico detallado del interior y el mobiliario del templo. La conexión con la raíz de ''tallar'' o ''grabar'' sugiere un trabajo artístico especializado que realzaba la belleza y el carácter sagrado del santuario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4735', 'spa', 'Ganado, animales domésticos como riqueza mueble; ocasionalmente el acto o resultado de una adquisición (de q-n-h, ''adquirir'').', 'Ganado, animales domésticos como riqueza mueble; ocasionalmente el acto o resultado de una adquisición (de q-n-h, ''adquirir'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4736', 'spa', 'Compra, adquisición — el acto de comprar, el precio pagado o la propiedad obtenida mediante una transacción.', 'Compra, adquisición — el acto de comprar, el precio pagado o la propiedad obtenida mediante una transacción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4740', 'spa', 'Esquina, contrafuerte angular — ángulo arquitectónico o punto de giro en un muro, altar o estructura edilicia.', 'El sustantivo מִקְצֹעַ (miqtsoa) designa una esquina o punto angular de giro en una estructura. Aparece en la construcción del tabernáculo, donde los bastidores de esquina se unen en ambos extremos (Éx 26:24; 36:29); en las reparaciones del muro de Nehemías, donde «el Ángulo» marca un punto específico de fortificación (Neh 3:19-20, 24-25); y en el templo visionario de Ezequiel, tanto para las esquinas del altar (Ez 41:22) como para los atrios cerrados de las esquinas (Ez 46:21-22). Segundo de Crónicas 26:9 registra que Uzías edificó una torre en el contrafuerte angular.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4743', 'spa', 'Pudrirse, descomponerse, consumirse; describe la descomposición física y el desgaste figurado bajo el juicio divino', 'Verbo atestiguado casi exclusivamente en la conjugación Nifal, que describe el proceso de pudrirse, supurar o consumirse. Posee una cualidad intensamente física: heridas que supuran en el Salmo 38:5, carne que se pudre en Zacarías 14:12 y cuerpos que se descomponen bajo la maldición divina en Levítico 26:39. También se extiende a la disolución cósmica, como cuando el ejército de los cielos se deshace en Isaías 34:4. Ezequiel lo emplea para el desgaste espiritual de Israel en el exilio, donde el pueblo se consume en sus iniquidades (Ez 4:17; 24:23; 33:10). Tanto el árabe yadhibuna (''se disuelven'') como el español ''consumirse'' captan la cualidad progresiva e irreversible de esta decadencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4744', 'spa', 'Convocación santa o asamblea sagrada; también el acto de leer o recitar las Escrituras', 'Convocación santa o asamblea sagrada; también el acto de leer o recitar las Escrituras');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4745', 'spa', 'Suceso, destino o suerte que le sobreviene a alguien; también casualidad o accidente sin causa divina aparente', 'Sustantivo derivado de la raíz qarah (''encontrar, sobrevenir''), esta palabra refleja la meditación hebrea sobre lo que les sucede a las personas y por qué. En Eclesiastés, Qohélet la emplea filosóficamente para argumentar que el mismo miqreh —la misma suerte— alcanza al sabio y al necio, a humanos y animales por igual (Ecl 2:14-15; 3:19; 9:2-3), indagando si los desenlaces de la vida revelan algún orden significativo. En cambio, en los contextos narrativos de Rut y 1 Samuel, la palabra denota pura coincidencia o accidente: el ''azar'' de Rut al llegar al campo de Booz (Rut 2:3), o los filisteos probando si la plaga del arca era miqreh y no un acto divino (1 Sam 6:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4749', 'spa', 'Obra batida a martillo, especialmente oro labrado para los utensilios del tabernáculo; posiblemente obra torneada', 'Término técnico de la artesanía sagrada de Israel, referido al trabajo en metal producido mediante martilleo y no por fundición. Casi todas las apariciones describen el oro batido del tabernáculo: los querubines labrados a martillo de una sola pieza (Éx 25:18; 37:7), el candelabro forjado como una obra continua batida a martillo desde su base hasta sus flores (Éx 25:31, 36; 37:17, 22; Nm 8:4), y las trompetas de plata moldeadas a golpe de martillo (Nm 10:2). El énfasis recae en la destreza del artesano al dar forma al metal precioso mediante golpes repetidos. Una aparición aislada en Jeremías 10:5, que compara los ídolos con un espantapájaros en un campo de pepinos, puede reflejar un homónimo no relacionado o un desarrollo semántico distinto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4751', 'spa', 'Amargo, amargura; describe sabor aspero, angustia emocional, temperamento feroz o llanto intensificado.', 'Amargo, amargura; describe sabor aspero, angustia emocional, temperamento feroz o llanto intensificado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4753', 'spa', 'Mirra: resina aromática costosa del árbol Commiphora, usada en el aceite sagrado, perfumes y preparación funeraria', 'El sustantivo מֹר (mor) designa la mirra, la preciada resina aromática apreciada en todo el antiguo Cercano Oriente. Encabeza la lista de especias del aceite sagrado de unción (Éx 30:23) y aparece en los preparativos de belleza de Ester (Est 2:12). El Cantar de los Cantares satura su imaginería con mirra: un saquito entre los pechos (Cnt 1:13), la montaña de mirra al amanecer (4:6) y mirra líquida que gotea de las manos del amado (5:5). El Salmo 45:8 perfuma las vestiduras del rey con mirra, áloes y casia. El español ''mirra'' y el árabe ''murr'' conservan la raíz semítica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4756', 'spa', 'Señor, amo: sustantivo arameo de tratamiento y título para Dios o un rey, usado en Daniel', 'Sustantivo arameo que significa ''señor'' o ''amo'', cognado del siríaco moro y emparentado con el hebreo adon. En Daniel funciona tanto como título para Dios — ''Señor de reyes'' (Dan 2:47), ''Señor del cielo'' (Dan 5:23) — como forma respetuosa de dirigirse al rey, ''mi señor'' (Dan 4:19, 24). La variación Ketiv/Qere (mor''i frente a mari) preserva una antigua distinción dialectal en el sufijo de primera persona. Esta palabra conecta con la tradición semítica más amplia de mare/maran, conocida por la oración cristiana primitiva maranatha (''Ven, Señor nuestro'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4758', 'spa', 'Vista, apariencia o visión; el aspecto exterior de una persona o cosa, una experiencia visionaria profética o el acto de ver', 'Sustantivo hebreo derivado del verbo רָאָה (ver), מַרְאֶה abarca todo el arco de la experiencia visual. En su uso más común describe la apariencia exterior — cómo se ve alguien o algo —, como cuando la Escritura nota la belleza de Sara (Gn 12:11) o de Raquel (Gn 29:17). En Ezequiel y Daniel adquiere peso profético, designando las visiones sobrenaturales mediante las cuales Dios revela sus propósitos (Ez 43:3). Con menor frecuencia se refiere al acto o facultad de ver en sí mismo, como en la perturbadora ''vista de tus ojos'' de Deuteronomio 28:34.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4759a', 'spa', 'Visión profética; revelación visual sobrenatural de Dios, que ocurre frecuentemente de noche o en estado de trance', 'Designa una visión divina concedida como medio de revelación, distinta de los sueños o la palabra audible. Dios declara en Números 12:6 que se da a conocer a los profetas ''en visión'' (mar''ah), estableciendo este modo junto con los sueños. El primer encuentro de Samuel con Dios se denomina mar''ah (1 Sam 3:15), y Ezequiel describe repetidamente sus experiencias de traslado como ''visiones de Dios'' (Ez 1:1; 8:3; 40:2). El plural constructo ''visiones de la noche'' (Gn 46:2) y ''visiones de Dios'' (Ez 1:1) subrayan el origen sobrenatural de la experiencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4762', 'spa', 'Maresa — ciudad en la Sefela de Judá; también nombre personal o de clan en la genealogía calebita', 'Nombre propio que identifica una ciudad en la Sefela (estribaciones occidentales) de Judá, probablemente la actual Tell Sandahanna cerca de Beit Jibrin. Maresa aparece en la lista de asignaciones de Josué (Jos 15:44), entre las fortificaciones de Roboam (2 Cr 11:8) y como escenario de la gran victoria de Asá sobre el ejército cusita de Zéraj (2 Cr 14:9-10). Miqueas 1:15 la incluye en la elegía profética sobre las ciudades de la Sefela. En las genealogías calebitas de 1 Crónicas 2:42 y 4:21, el nombre aparece como designación de clan o persona, reflejando el patrón de asentamiento de la región.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4763', 'spa', 'Cabecera, lugar junto a la cabeza — el sitio al lado o debajo de la cabeza de alguien mientras duerme o descansa', 'El sustantivo מְרַאֲשׁוֹת (mera''ashot) designa el área junto a la cabeza de una persona mientras duerme. Jacob coloca una piedra en su cabecera antes de dormir en Betel (Gn 28:11, 18). Mical pone el ídolo doméstico en la cabecera de David para engañar a los hombres de Saúl (1 S 19:13, 16). David se infiltra en el campamento de Saúl y encuentra la lanza del rey en su cabecera, tomándola como prueba de misericordia (1 S 26:7, 11-12, 16). Elías despierta y halla provisiones en su cabecera (1 R 19:6). La palabra siempre implica proximidad y vulnerabilidad durante el sueño.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4764', 'spa', 'Merab, la hija mayor de Saúl, prometida a David pero entregada a otro hombre', 'Merab fue la hija primogénita del rey Saúl, mencionada por primera vez junto a su hermana Mical en la genealogía de 1 Samuel 14. Saúl la prometió a David como esposa a cambio de hazañas militares contra los filisteos, pero llegado el momento, la entregó a Adriel el meholatita. Esta promesa incumplida formó parte del patrón de Saúl de usar a sus hijas como peones en su conflicto con David. Su nombre aparece en solo tres versículos, señalándola como figura de pacto roto y manipulación real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4768', 'spa', 'aumento, gran numero, abundancia; interes sobre alimentos; la mayor parte; grandeza (de sabiduria)', 'Sustantivo que denota aumento o abundancia en diversas aplicaciones concretas y abstractas. En Levitico 25:37 se refiere especificamente al interes o recargo sobre los alimentos, emparejado con nesek (usura sobre el dinero), reflejando la legislacion crediticia del antiguo Cercano Oriente. Puede indicar la mayor parte de un grupo (1 Cr 12:30) o la grandeza de algo abstracto como la sabiduria (2 Cr 9:6). Los terminos ''abundancia'' y ''multitud'' captan bien la amplitud cuantitativa de esta palabra, que abarca desde lo familiar y concreto hasta lo abstracto y sublime.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4770', 'spa', 'marbeq — establo, lugar de engorde para alimentar ganado, especialmente becerros', 'Este sustantivo significa literalmente ''lugar donde se ata'' o ''establo'', y se refiere a un recinto donde los animales se ataban y engordaban para el eventual sacrificio. El término aparece cuatro veces, siempre en relación con becerros, destacando la práctica de alimentación en establo para producir animales bien cebados. Se dan usos tanto literales como figurados: Saúl ofrece un ''becerro de engorde'' como comida en 1 Samuel, mientras que los profetas emplean ''becerros del establo'' como metáforas de prosperidad (Malaquías), riqueza arrogante (Jeremías) y lujo desmedido (Amós). La cría en establo representaba un lujo, pues la mayoría del ganado pastaba libremente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4772', 'spa', 'Lugar a los pies, zona de los pies: el sitio junto a los pies de alguien, especialmente donde uno se acuesta', 'Sustantivo femenino plural derivado de regel (''pie''), que designa el lugar junto a los pies de alguien o en su cercanía. Aparece casi exclusivamente en el libro de Rut, en la célebre escena de la era donde Noemí instruye a Rut que descubra ''el lugar de sus pies'' y se acueste allí (Rut 3:4, 7, 8, 14). Su única otra aparición, Daniel 10:6, describe el aspecto resplandeciente de las extremidades inferiores de la figura angélica. La palabra se distingue cuidadosamente de regel en sí: margelot enfatiza la ubicación o zona más que la parte del cuerpo, añadiendo una dimensión espacial y quizás eufemística a la narrativa de Rut.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4775', 'spa', 'Rebelarse o sublevarse contra la autoridad; también usado como sustantivo para los rebeldes — quienes desafían a un soberano, señor o a Dios', 'Rebelarse o sublevarse contra la autoridad; también usado como sustantivo para los rebeldes — quienes desafían a un soberano, señor o a Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4782', 'spa', 'Mardoqueo: el líder judío en la corte persa, primo y padre adoptivo de Ester, héroe de la narración de Purim.', 'Mardoqueo: el líder judío en la corte persa, primo y padre adoptivo de Ester, héroe de la narración de Purim.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4784', 'spa', 'Ser rebelde, contencioso o desobediente; desafiar la autoridad, especialmente los mandamientos de Dios; tambien provocacion amarga.', 'Ser rebelde, contencioso o desobediente; desafiar la autoridad, especialmente los mandamientos de Dios; tambien provocacion amarga.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4785', 'spa', 'Mara, el manantial amargo que Israel encontro en el desierto del Sinai despues del Exodo', 'Mara es el nombre de lugar dado a un manantial en la peninsula del Sinai cuyas aguas eran demasiado amargas para beber (Exodo 15:23). El nombre deriva de la raiz que significa ''amargo,'' y la narracion relata como Dios endulzo las aguas mediante un arbol arrojado en ellas. Numeros 33:8-9 menciona a Mara como estacion en el itinerario de Israel por el desierto. El nombre se convirtio en emblema de la prueba transformada por la provision divina, recordando que la amargura del camino puede ser sanada por la intervención de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4788', 'spa', 'Condición de no tener hogar, vagabundeo o estado de ser expulsado sin refugio', 'Este término describe la condición de carecer de hogar o de andar errante, sin un techo estable donde guarecerse. Isaías lo emplea al ordenar al pueblo de Dios que acoja en sus casas a los «pobres sin hogar». Lamentaciones lo usa dos veces para retratar la miseria de Jerusalén: sus vagabundeos en días de aflicción y el recuerdo amargo del sufrimiento y la errancia que atormenta el alma. No solo abarca el desplazamiento físico, sino también la desolación emocional y social de quien no tiene un lugar donde pertenecer ni descansar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4791', 'spa', 'Altura, lugar elevado o alturas celestiales; usado para cumbres físicas, la morada celestial de Dios y como título de exaltación divina.', 'Altura, lugar elevado o alturas celestiales; usado para cumbres físicas, la morada celestial de Dios y como título de exaltación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4794', 'spa', 'carrera, modo de correr; curso de vida o conducta moral', 'Sustantivo femenino derivado de la raiz רוּץ (''correr'') que designa tanto el acto fisico y el estilo de correr como, en sentido figurado, el curso o rumbo de la vida y la conducta moral de una persona. En 2 Samuel 18:27, el centinela reconoce a Ahimaaz por su manera caracteristica de correr. Jeremias emplea el termino para describir el rumbo moral desviado del pueblo (Jer 8:6; 23:10). El espanol ''carrera'' abarca con naturalidad ambas dimensiones, la atletica y la figurada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4800', 'spa', 'Lugar amplio, espacio abierto: área espaciosa, frecuentemente figurativa de la liberación divina de la angustia', 'Sustantivo masculino que significa un lugar amplio, holgado o espacioso, derivado de la raíz r-kh-b (''ser ancho''). Si bien puede denotar una extensión física — un pastizal en Oseas 4:16 o ''los anchos de la tierra'' en Habacuc 1:6 — su uso más poderoso es metafórico. En 2 Samuel 22:20 y el Salmo 18:19, Dios lleva al liberado ''a lugar espacioso'', imagen de libertad tras la constricción. Los Salmos 31:8 y 118:5 retoman esta imagen, retratando el rescate divino como la emergencia desde la estrechez hacia el espacio abierto. La metáfora espacial resuena a través de los idiomas: en español ''lugar espacioso'', en francés ''large espace''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4801', 'spa', 'Lugar distante, lejanía — distancia o regiones remotas, frecuentemente en la frase ''desde lejos''', 'Lugar distante, lejanía — distancia o regiones remotas, frecuentemente en la frase ''desde lejos''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4803', 'spa', 'Alisar, pulir o frotar; pulir o bruñir un arma; arrancar cabello por duelo o agravio; quedarse calvo', 'Un verbo de acción enérgica sobre superficies, ya sea raspar metal hasta dejarlo reluciente o arrancar cabello del cuero cabelludo. En los oráculos de la espada de Ezequiel, la hoja está «pulida» para la matanza, una imagen aterradora del juicio divino preparado. Sin embargo, la misma raíz describe a Esdras arrancándose el cabello por angustia ante los matrimonios que violaban el pacto, y al Siervo de Isaías ofreciendo sus mejillas a quienes le arrancan la barba. La amplitud semántica es notable: el brillo de un arma y la crudeza del duelo comparten una sola raíz hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4805', 'spa', 'Rebelión, desafío — resistencia obstinada contra Dios o la autoridad legítima, especialmente la desobediencia crónica de Israel', 'Rebelión, desafío — resistencia obstinada contra Dios o la autoridad legítima, especialmente la desobediencia crónica de Israel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4806', 'spa', 'Animal cebado, res engordada — ganado vacuno u ovino especialmente engordado para banquete o sacrificio', 'Sustantivo masculino que designa un animal cebado — una res (generalmente becerro, buey u oveja) engordada con pastos ricos o grano para el sacrificio o el banquete. Aparece en contextos de suntuosos festines reales, como cuando Adonías sacrificó ''bueyes y animales cebados'' al disputar el trono (1 R 1:9, 19, 25), y en la crítica profética contra el ritualismo vacío (Is 1:11; Am 5:22). La visión de paz de Isaías muestra ''el becerro, el león joven y el animal engordado juntos'' (Is 11:6), y el banquete apocalíptico de Ezequiel incluye ''engordados de Basán'' (Ez 39:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4807', 'spa', 'Merib-Baal, hijo de Jonatán y nieto de Saúl, también llamado Mefiboset', 'Este nombre aparece en las genealogías de 1 Crónicas para designar al hijo de Jonatán, más conocido en 2 Samuel como Mefiboset. La doble denominación refleja la práctica escribal antigua de reemplazar el elemento «Baal» por «boset» (vergüenza) en textos posteriores, para evitar pronunciar el nombre de la deidad cananea. Merib-Baal significa «Baal es defensor» o posiblemente «héroe de Baal». El nombre aparece tres veces en la genealogía de Crónicas, identificando al mismo individuo que quedó lisiado de niño y a quien David trató con bondad por amor a Jonatán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4808', 'spa', 'Meribá (lugar de contienda donde Israel disputó con Dios por agua); también sustantivo común: contienda, disputa', 'Derivado de la raíz rîv (''contender, disputar''), este vocablo aparece tanto como nombre propio como sustantivo común. Como topónimo, Meribá señala el lugar donde Israel contendió con Dios por agua en el desierto, especialmente en Meribá-Cades, donde Moisés golpeó la roca (Dt 32:51; Sal 95:8). Como sustantivo común significa simplemente ''contienda'' o ''disputa'', como cuando Abraham dice a Lot: ''No haya contienda entre tú y yo'' (Gn 13:8). La evidencia multilingüe confirma la distinción: las traducciones transliteran uniformemente el topónimo, mientras que traducen el sustantivo común con palabras nativas para riña o disputa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4809', 'spa', 'Meribah: topónimo que significa ''contienda/querella,'' donde Israel disputó con Dios por el agua.', 'Nombre propio que significa ''contienda'' o ''querella,'' aplicado al lugar (o lugares) donde Israel puso a prueba a Dios reclamando agua. Se distinguen dos incidentes: uno en Refidim al inicio de la travesía por el desierto (Éx 17:7, junto con Masah) y otro en Cades hacia el final (Nm 20:13, 24; 27:14; Dt 32:51; 33:8). La expresión mei meribah (''aguas de Meribah'') se convirtió en sinónimo del espíritu rebelde de Israel, evocada en los salmos como advertencia (Sal 81:8; 95:8; 106:32). La Septuaginta traduce el nombre de formas variadas: antilogia (''contradicción'') y parapikrasmos (''provocación'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4812', 'spa', 'Merayot — nombre sacerdotal llevado por ancestros de Sadoc y una casa sacerdotal postexílica', 'Nombre propio masculino que significa quizá ''rebeliones'' o ''amargos'', llevado por al menos dos figuras sacerdotales en la Biblia hebrea. El Merayot principal es descendiente de Aarón en la genealogía sumo sacerdotal, abuelo de Ajitub y bisabuelo de Sadoc (1 Cr 5:32-33; 6:37; Esd 7:3). Un segundo aparece como hijo de Ajitub y padre de Sadoc en 1 Crónicas 9:11 y Nehemías 11:11. El nombre también designa una casa sacerdotal en Nehemías 12:15, posiblemente un error por Meremot. La Septuaginta lo traduce de diversas formas: Maraioth, Marmoth y Mareioth.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4813', 'spa', 'Miriam -- profetisa y hermana de Moises y Aaron; tambien un hombre judahita en 1 Cronicas 4:17', 'Miriam -- profetisa y hermana de Moises y Aaron; tambien un hombre judahita en 1 Cronicas 4:17');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4817', 'spa', 'Asiento para montar: carro, silla de montar o litera para viaje montado', 'Este término designa un asiento o plataforma para cabalgar, ya sea en un carro de guerra, sobre un animal o en un palanquín. Las vastas fuerzas de carros de Salomón requerían este tipo de equipo (1 Re 5). Levítico 15 lo menciona en las leyes de pureza relativas al contacto con una silla de montar usada por alguien con flujo. El Cantar de los Cantares lo emplea para el asiento de la ornamentada litera de Salomón. El hilo común es un asiento construido que eleva al jinete, sea para la guerra, el transporte o la procesión ceremonial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4818', 'spa', 'carro — vehículo tirado por caballos usado en la guerra, procesiones reales o transporte', 'carro — vehículo tirado por caballos usado en la guerra, procesiones reales o transporte');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4820', 'spa', 'Engaño, traición, fraude — deshonestidad en el habla, el comercio o las relaciones interpersonales', 'Engaño, traición, fraude — deshonestidad en el habla, el comercio o las relaciones interpersonales');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4822', 'spa', 'Meremot — nombre sacerdotal llevado por varios individuos de la comunidad postexílica (Esdras, Nehemías).', 'Nombre propio masculino que aparece en los libros postexílicos de Esdras y Nehemías. Meremot fue sacerdote en tiempos de Zorobabel (Neh 12:3), y otro Meremot hijo de Urías supervisó el pesaje de la plata y el oro del templo al regreso de Babilonia (Esd 8:33), además de colaborar en la reconstrucción de dos secciones de la muralla de Jerusalén (Neh 3:4, 21). Un tercer Meremot figura entre quienes habían tomado esposas extranjeras (Esd 10:36). La Septuaginta transcribe el nombre de diversas maneras —Mareimouth, Mereimouth, Ieramoth— reflejando la fluidez en la transliteración griega de grupos consonánticos hebreos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4823', 'spa', 'Pisoteo, lugar pisoteado -- lo hollado bajo los pies, usado literal y figuradamente para destrucción total.', 'Sustantivo masculino que designa el pisoteo o un lugar hollado bajo los pies. Isaías lo emplea como imagen poderosa de destrucción total: una viña entregada al pisoteo (Is 5:5), colinas convertidas en terreno pisoteado por el ganado (Is 7:25), Asiria como instrumento de Dios para hacer de las naciones ''un pisoteo como lodo de las calles'' (Is 10:6), y un pacto con la muerte que será pisoteado (Is 28:18). Miqueas 7:10 vuelve la imagen contra los enemigos de Israel, subrayando la humillación física y total que conlleva este término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4828', 'spa', 'Amigo íntimo, compañero, confidente -- persona unida por lealtad personal y trato cercano.', 'Sustantivo masculino que denota un amigo íntimo o compañero de confianza, distinto del más general רֵעַ (''prójimo''). Implica un vínculo de lealtad personal y confianza. Ahuzat, ''amigo'' de Abimelec (Gn 26:26), servía como consejero y confidente real. El término aparece de manera destacada en la historia de Sansón para referirse a sus compañeros de boda y al ''amigo del novio'' a quien fue entregada su esposa (Jue 14:11, 20; 15:2, 6). En Proverbios 19:7 aparece en la sobria observación de cómo hasta los amigos cercanos se distancian del pobre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4829', 'spa', 'Pasto, pastizal -- lugar de apacentamiento para el ganado; figuradamente, la provision de Dios para su pueblo', 'Pasto, pastizal -- lugar de apacentamiento para el ganado; figuradamente, la provision de Dios para su pueblo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4830', 'spa', 'Pasto o rebaño; siempre figurado en las Escrituras para el pueblo de Dios como las ovejas que Él apacienta y protege', 'Sustantivo femenino que significa apacentamiento, pasto o, por metonimia, rebaño. En cada aparición bíblica se usa figuradamente: Israel es «las ovejas de su pasto» (Sal 95:7; 100:3), y los profetas se lamentan cuando el rebaño de Dios es dispersado (Jer 23:1). La palabra siempre lleva un sufijo posesivo, enfatizando el vínculo pactual entre pastor y ovejas. En un caso notable (Jer 10:21), el término pasa del lugar de pastoreo a los animales mismos — «su rebaño fue dispersado» — una metonimia natural que todas las lenguas confirman.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4832', 'spa', 'Sanidad, cura o remedio; figuradamente compostura o calma que restaura el bienestar', 'Sanidad, cura o remedio; figuradamente compostura o calma que restaura el bienestar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4834', 'spa', 'nimrats — grave, doloroso, severo (describe un juicio destructivo o una aflicción intensa)', 'Este término hebreo, derivado de la raíz מרץ, describe algo grave, doloroso o severo. Aunque en lenguas semíticas emparentadas la raíz puede significar ''estar enfermo'', en el hebreo bíblico funciona como intensificador, enfatizando la severidad o dureza de algo. Aparece en contextos de maldición (1 Reyes), discurso provocador (Job) y juicio divino (Miqueas). Existe debate académico sobre Job 6:25, donde algunos sugieren que podría significar ''fuerte'' o ''eficaz'' en lugar de ''doloroso'', posiblemente relacionado con una raíz acadia distinta que significa ''difícil'' o ''repelente''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4838', 'spa', 'maraq — fregar, pulir o limpiar a fondo (metales, vasijas o, en sentido figurado, el alma)', 'Este verbo significa fregar, pulir o limpiar a fondo, empleado tanto en sentido literal para el trabajo con metales como en sentido figurado para la purificación moral. La raíz aparece en lenguas semíticas afines con significados similares de raspar o pulir. En la Biblia se usa para pulir utensilios de bronce del templo, fregar vasijas sacrificiales para la pureza ritual y, metafóricamente, para el efecto purificador de la disciplina. El término sugiere una limpieza intensiva y completa que devuelve el brillo al metal o la pureza a una vasija, y por extensión, al carácter de una persona mediante el sufrimiento correctivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4839', 'spa', 'Caldo o jugo extraído al cocer carne, a veces ritualmente impuro', 'Este término culinario aparece en dos contextos distintos: la ofrenda de Gedeón al ángel (Jue 6) y la condena de Isaías contra quienes comen cosas inmundas (Is 65). En ambos casos se refiere al líquido que se extrae al cocinar la carne: el caldo. Cuando Gedeón prepara su ofrenda, pone la carne en una canasta y el caldo en una olla. Isaías denuncia a quienes beben «caldo de cosas inmundas», probablemente referido a caldos de cerdo u otras carnes prohibidas. El término capta la esencia o extracto de la carne concentrado en forma líquida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4842', 'spa', 'Mezcla de ungüento o preparación de aceites perfumados y especias', 'Este término se refiere a la habilidad de mezclar ingredientes aromáticos para elaborar ungüentos o perfumes. Éxodo lo emplea para el aceite sagrado de la unción, preparado «conforme al arte del perfumista». Crónicas menciona a quienes se especializaban en esta labor, los «preparadores del ungüento». Cuando el rey Asá murió, fue sepultado «en un lecho de especias compuestas», probablemente una mezcla aromática preparada con arte. El énfasis recae en la elaboración experta: el arte de combinar múltiples ingredientes en una sustancia fragante y unificada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4843', 'spa', 'Ser amargo; amargar, hacer amargo; enfurecerse; llorar o lamentar amargamente (Qal, Piel, Hifil, Hitpael)', 'Ser amargo; amargar, hacer amargo; enfurecerse; llorar o lamentar amargamente (Qal, Piel, Hifil, Hitpael)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4844', 'spa', 'Hierbas amargas consumidas con la cena de Pascua, simbolizando la amargura de la esclavitud en Egipto', 'Se refiere a las plantas amargas —probablemente endivias, achicorias u hojas similares— que debían comerse con el cordero pascual como memorial de la amarga esclavitud de Israel en Egipto. La instrucción aparece tanto en Éxodo 12 como en Números 9, vinculando el sabor físico de la amargura con el recuerdo de la opresión. Lamentaciones emplea el término metafóricamente, describiendo el juicio de Dios como ser saciado con «hierbas amargas», es decir, un sufrimiento que llena la boca de amargura. Las hierbas funcionan como memoria comestible: el sabor que codifica la historia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4846', 'spa', 'merorot — cosas amargas, hiel, veneno; hígado literal o amargura figurada', 'Este sustantivo designa cosas amargas, hiel o veneno, utilizado tanto en sentido anatómico como metafórico. Puede referirse a la vesícula biliar como órgano, a sustancias venenosas, o figuradamente a experiencias amargas y juicios severos. Las cuatro apariciones se encuentran en literatura poética (el cántico de Deuteronomio y los discursos de Job), donde la amargura sirve como imagen poderosa del sufrimiento, el juicio o la naturaleza letal de la maldad. La imagen se basa en la experiencia física de lo amargo para transmitir realidades espirituales y existenciales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4847', 'spa', 'Merari — tercer hijo de Leví; antepasado del clan levítico merarita que servía en el tabernáculo y el templo', 'Merari — tercer hijo de Leví; antepasado del clan levítico merarita que servía en el tabernáculo y el templo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4853a', 'spa', 'Carga, peso; también oráculo profético, tributo o elevación del deseo — de la raíz נָשָׂא ''levantar, cargar''', 'Carga, peso; también oráculo profético, tributo o elevación del deseo — de la raíz נָשָׂא ''levantar, cargar''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4853b', 'spa', 'Oráculo, carga profética — pronunciamiento divino solemne que generalmente introduce juicios contra las naciones', 'Oráculo, carga profética — pronunciamiento divino solemne que generalmente introduce juicios contra las naciones');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4855', 'spa', 'Préstamo, deuda o la práctica de cobrar interés (usura)', 'Este término aparece exclusivamente en las reformas de Nehemías, donde aborda la opresión económica entre judíos mediante prácticas de préstamo. Aunque algunas traducciones lo vierten como «carga» o «deuda», el contexto se refiere a préstamos con interés. Nehemías confronta a los nobles por exigir intereses a los israelitas pobres, exigiendo que devuelvan lo cobrado y cesen la usura. El vocablo abarca tanto el acto de prestar como la carga que tales préstamos imponían al combinarse con intereses, violando las obligaciones de solidaridad del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4863', 'spa', 'misharot — artesas o bateas para amasar, recipientes domésticos para preparar masa de pan', 'Este sustantivo femenino designa artesas o bateas para amasar, los recipientes domésticos donde se mezclaba y preparaba la masa antes de hornear. Aunque tradicionalmente se ha vinculado a la palabra para ''levadura'', esta derivación es incierta. Estos utensilios aparecen de forma prominente en las narraciones del Éxodo: en la plaga de ranas que las invadió y en la salida apresurada cuando Israel llevó su masa en las artesas. También figuran en las bendiciones y maldiciones de Deuteronomio, simbolizando la provisión del hogar y el sustento diario. Como implementos esenciales de cocina, las artesas representaban las necesidades básicas de la vida doméstica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4864', 'spa', 'Un alzamiento; de ahí una porción o regalo, una señal de fuego, un tributo o impuesto, una carga u oráculo, o el alzar de manos', 'Un alzamiento; de ahí una porción o regalo, una señal de fuego, un tributo o impuesto, una carga u oráculo, o el alzar de manos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4865', 'spa', 'Engastes de filigrana o monturas de oro trenzado para piedras preciosas, usados en las vestiduras sacerdotales del tabernáculo.', 'Sustantivo que designa monturas ornamentales de oro — trabajo de filigrana o entramado metálico diseñado para sujetar piedras preciosas con firmeza — que aparece casi exclusivamente en las instrucciones detalladas para el efod y el pectoral del sumo sacerdote (Éx 28-29, 39). La artesanía consistía en entretejer hilo de oro formando armazones a modo de canastillo que albergaban cada gema. El término alemán ''Einfassungen'' (engarces) y el español ''engastes'' captan bien el sentido funcional: no son meros adornos, sino monturas de precisión. Una bella extensión aparece en el Salmo 45:14, donde el vestido de la novia real se describe con labor de oro semejante, trazando una línea poética desde el esplendor sacerdotal hasta el ornato regio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4866', 'spa', 'La abertura del vientre, el momento en que el parto irrumpe', 'Este vívido término describe el momento crítico del parto en que el bebé alcanza la abertura del canal de nacimiento pero la entrega aún no se ha completado. Tanto Reyes como Isaías emplean un lenguaje idéntico: «Los hijos han llegado al punto de nacer, pero no hay fuerza para dar a luz», metáfora de una crisis en la que el momento de la liberación ha llegado pero falta el poder para consumarla. Oseas lo usa para describir la necedad de Efraín al demorarse «en la abertura del vientre». La imagen es la de estar atrapado en el umbral, incapaz de avanzar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4867', 'spa', 'rompiente, ola que revienta; usado literalmente del oleaje y figuradamente de calamidad abrumadora', 'Sustantivo masculino que significa ''rompiente'' u ''ola que revienta'', y que aparece siempre en plural. El Salmo 93:4 lo emplea literalmente para las majestuosas olas del mar como evidencia del poder supremo de Dios. Con mayor frecuencia funciona como potente metafora de tribulacion abrumadora: los rompientes de la muerte en 2 Samuel 22:5, o las olas de Dios que barren al salmista (Sal 42:7; 88:7). Jonas 2:3 lo combina memorablemente con ''tus olas'', vinculando la fuerza literal del oceano con la soberania divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4869a', 'spa', 'Refugio alto, fortaleza elevada: un lugar de seguridad en las alturas, usado abrumadoramente como metáfora de Dios como protector. El sustantivo מִשְׂ', 'Refugio alto, fortaleza elevada: un lugar de seguridad en las alturas, usado abrumadoramente como metáfora de Dios como protector. El sustantivo מִשְׂגָּב describe una fortaleza inaccesible o refugio elevado, derivado de la raíz שָׂגַב (''ser alto, exaltado''). Aunque puede referirse a un baluarte físico —Isaías describe las murallas fortificadas de Moab como un מִשְׂגָּב que será derribado (Is 25:12)—, su uso dominante es metafórico: los Salmos lo aplican a Dios como refugio alto del creyente no menos de doce veces. La palabra aparece en densas agrupaciones de lenguaje de confianza junto a términos como ''roca,'' ''fortaleza'' y ''escudo,'' notablemente en el Salmo 18:2 (= 2 Sam 22:3) y el estribillo de los Salmos 46 y 59. Su duplicación en el Salmo 9:9 —''El SEÑOR es מִשְׂגָּב para el oprimido, מִשְׂגָּב en tiempos de angustia''— lo convierte en un término emblemático de la teología de protección divina del Salterio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4871', 'spa', 'Sacar o extraer, especialmente del agua o del peligro', 'Este raro verbo aparece solo tres veces: dos en pasajes paralelos y una en la imposición del nombre de Moisés. Éxodo 2:10 lo usa para explicar el nombre Moisés (Moshé): «Porque de las aguas lo saqué». El verbo se vincula al rescate milagroso del niño del Nilo. Los dos paralelos de Salmos y Samuel lo emplean para la liberación divina: «Me sacó de las muchas aguas», Dios extrayendo al salmista de un peligro abrumador. La imagen es de extracción: arrancar a alguien de un peligro envolvente hacia la seguridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4872', 'spa', 'Moisés — el legislador, profeta y líder que sacó a Israel de Egipto', 'מֹשֶׁה se erige como la figura central de la Torá, con 766 apariciones desde Éxodo hasta el final de la Biblia hebrea. Su nombre, probablemente derivado del egipcio mes (''hijo, nacido de''), fue reinterpretado por la hija del Faraón como ''sacado de las aguas'' (Éx 2:10). Como mediador del pacto sinaítico, Moisés ocupa un papel singular: profeta, legislador, intercesor y pastor de una nación. La evidencia multilingüe —español ''Moisés'', francés ''Moïse'', alemán ''Mose''— muestra el reconocimiento universal de este nombre propio, sin ninguna fragmentación semántica en tradición alguna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4875', 'spa', 'Desolación, devastación o ruina total y completa', 'Este sustantivo describe una devastación absoluta: lugares o vidas reducidos a páramo. Aparece en parejas poéticas con otros términos de destrucción. La descripción de Sofonías del Día del Señor lo llama «día de devastación y desolación». Job lo emplea dos veces: una para vidas consumidas por la carencia y el hambre que «roen la tierra reseca», y otra para la voz de Dios que truena en «el desierto desolado». El término evoca vacío, páramo aullante, la secuela de una destrucción total donde no queda sino escombros y silencio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4878', 'spa', 'Apostasia, deslealtad, alejamiento de Dios; tambien usado como cuasi-adjetivo: apostata, infiel (referido a personas)', 'Apostasia, deslealtad, alejamiento de Dios; tambien usado como cuasi-adjetivo: apostata, infiel (referido a personas)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4884', 'spa', 'mesurah — medida, capacidad (de líquidos o en general)', 'Este sustantivo significa ''medida'' o ''capacidad'', refiriéndose a la cantidad o proporción de algo, particularmente en contextos de regulación cuidadosa. El término aparece en textos legales y rituales donde la precisión importa. Se encuentra en Levítico respecto a prácticas comerciales justas, en Crónicas respecto al servicio del templo, y en la profecía simbólica actuada de Ezequiel donde incluso el agua y el pan deben medirse con exactitud. El énfasis recae en porciones controladas y precisas, no en la abundancia, sugiriendo a menudo limitación, disciplina o administración cuidadosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4885', 'spa', 'Gozo, exultación, deleite: alegría intensa o regocijo festivo, frecuentemente asociado con la música, las ciudades o el favor de Dios. מָשׂוֹשׂ es un ', 'Gozo, exultación, deleite: alegría intensa o regocijo festivo, frecuentemente asociado con la música, las ciudades o el favor de Dios. מָשׂוֹשׂ es un sustantivo abstracto que denota gozo, exultación o deleite, y aparece 17 veces en contextos predominantemente poéticos y proféticos. Se superpone estrechamente con שָׂשׂוֹן (H8342) pero posee un matiz propio, adhiriéndose a menudo a fuentes concretas de deleite: ciudades, instrumentos, modos de vida. Isaías lo usa para describir la música gozosa silenciada por el juicio: ''cesó el gozo de los panderos, terminó la exultación de los que se alegran, cesó el gozo de la lira'' (Is 24:8). La desolación de ciudades otrora gozosas es tema recurrente (Is 32:13-14). Sin embargo, Isaías también invierte la imagen: Jerusalén será ''gozo de muchas generaciones'' (Is 60:15), y el Salmo 48:2 llama a Sion ''el gozo de toda la tierra.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4886', 'spa', 'Untar o ungir con aceite; especialmente para consagrar reyes, sacerdotes y objetos sagrados; también para aplicar pintura o aceite cosmético. El verbo', 'Untar o ungir con aceite; especialmente para consagrar reyes, sacerdotes y objetos sagrados; también para aplicar pintura o aceite cosmético. El verbo por excelencia de la consagración sagrada en la Biblia hebrea, del cual deriva el título ''Mesías'' (מָשִׁיחַ, ''ungido''). Se vierte o unta aceite sobre personas y objetos para apartarlos al servicio divino: reyes como Saúl y David, sacerdotes como Aarón y sus hijos, y mobiliario sagrado como el tabernáculo y el altar. El cognado árabe مَسَحَ revela el gesto físico original de frotar o pasar la mano. Un puñado de apariciones conservan el significado más antiguo y no sacral de untar una sustancia sobre una superficie, como pintar paredes con bermellón (Jer 22:14) o aplicarse aceite cosmético (Amós 6:6), recordándonos que el sentido sagrado creció a partir de una acción física cotidiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4888a', 'spa', 'Aceite de unción, porción consagrada — el aceite sagrado para la consagración sacerdotal y una asignación dedicada al sacerdocio', 'Aceite de unción, porción consagrada — el aceite sagrado para la consagración sacerdotal y una asignación dedicada al sacerdocio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4889', 'spa', 'Destrucción, ruina; como agente personificado, el Destructor enviado en juicio divino (Ex 12:23; Jer 51:25)', 'Derivado de la raíz sh-ch-t (corromper, destruir), este sustantivo denota ruina física o devastación, frecuentemente como instrumento del juicio de Dios sobre naciones o individuos. En Éxodo 12:13 el Señor promete que «la plaga no estará entre vosotros para destrucción» cuando hiera a Egipto, mientras que Ezequiel lo emplea para las flechas del hambre enviadas «para destrucción» (5:16). En un giro figurativo notable, Jeremías 51:25 llama a Babilonia «oh monte destruidor» (har ha-mashchit), personificando a todo un imperio como agente de ruina. El uso relacionado en 2 Reyes 23:13 para la estribación sur del Monte de los Olivos — «el monte de la corrupción» donde había altares idolátricos — podría reflejar un juego de palabras deliberado con har ha-mishchah («monte de la unción»).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4898', 'spa', 'Mesezabel, nombre propio que significa ''Dios libera'', usado en la comunidad postexílica de Nehemías', 'Este nombre aparece asociado a tres hombres distintos en la comunidad postexílica de la época de Nehemías. Deriva de raíces arameas que significan ''Dios rescata'' o ''Dios libera'', reflejando el vocabulario teológico de la comunidad de la restauración. Un Mesezabel fue abuelo de un reconstructor del muro, otro selló el pacto, y un tercero fue padre de un funcionario real de Judá. No queda claro si se trata de tres individuos diferentes o de miembros emparentados, pero el nombre mismo da testimonio de la fe en el poder liberador de Dios durante el difícil período persa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4899', 'spa', 'Ungido; un rey, sacerdote o líder consagrado con aceite, culminando en el Mesías escatológico', 'Ungido; un rey, sacerdote o líder consagrado con aceite, culminando en el Mesías escatológico');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4900', 'spa', 'Sacar, tirar, arrastrar; atraer, prolongar, extender; prolongar un sonido o empuñar un arma', 'Sacar, tirar, arrastrar; atraer, prolongar, extender; prolongar un sonido o empuñar un arma');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4902', 'spa', 'Mesec, pueblo y región de Asia Menor (Anatolia) descendiente de Jafet, frecuentemente emparejado con Tubal en la profecía.', 'Mesec identifica un grupo étnico del linaje de Jafet (Gn 10:2; 1 Cr 1:5), conocido en los registros asirios como los mushki y en fuentes griegas como los moschoi, asentados en Armenia occidental y el centro de Anatolia. En los profetas, Mesec aparece casi invariablemente junto a Tubal como socios comerciales (Ez 27:13) y como naciones sujetas al juicio divino (Ez 32:26; 38:2-3; 39:1). El lamento del salmista «¡Ay de mí, que habito en Mesec!» (Sal 120:5) emplea el nombre para evocar una tierra lejana y hostil. Las formas ''Mesec'' en español, ''Meschek'' en francés y ''Mosoch'' en la Septuaginta reflejan la misma raíz consonántica semítica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4903', 'spa', 'Cama, lecho, lugar de reposo — sustantivo arameo para el sitio donde se duerme, usado solo en las visiones de Daniel.', 'Sustantivo masculino arameo que significa ''cama'' o ''lecho,'' presente únicamente en el libro de Daniel. Aparece seis veces, siempre con sufijos pronominales (''mi cama,'' ''tu cama,'' ''su cama''), describiendo el lugar donde figuras reales reciben visiones nocturnas. En Daniel 2:28-29 Dios revela a Nabucodonosor ''las visiones de tu cabeza sobre tu cama,'' y en Daniel 4:5-13 y 7:1 las visiones llegan mientras se está acostado. Las glosas en español (mi-cama, tu-cama, cama-de-él) reflejan fielmente la variación pronominal, confirmando que se trata de un único sentido léxico con flexión gramatical.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4904', 'spa', 'Cama o lecho para dormir; por extensión, dormitorio, acto de acostarse o eufemismo para relaciones sexuales', 'Cama o lecho para dormir; por extensión, dormitorio, acto de acostarse o eufemismo para relaciones sexuales');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4905', 'spa', 'Maskil -- termino en los titulos de salmos, que probablemente indica un poema contemplativo o compuesto con destreza artistica', 'Maskil -- termino en los titulos de salmos, que probablemente indica un poema contemplativo o compuesto con destreza artistica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4906', 'spa', 'Imagen tallada o piedra labrada (a menudo idolátrica); imaginación o presunción; engaste u ornamento artesanal.', 'En su raíz, maskit designa algo exhibido o hecho visible: una pieza de muestra. En contextos cultuales se refiere a imágenes talladas o piedras labradas asociadas con la idolatría, que la Torá prohíbe expresamente (Lv 26:1; Nm 33:52). Ezequiel 8:12 lo emplea para las secretas ''cámaras de imágenes'' donde los ancianos adoran abominaciones pintadas. Sin embargo, la misma raíz puede describir la vida interior: en el Salmo 73:7 las ''imaginaciones del corazón'' desbordan arrogancia. En su faceta más bella, Proverbios 25:11 transforma la palabra en un engaste ornamental: ''manzanas de oro en engastes de plata,'' celebrando el arte de la palabra bien escogida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4908', 'spa', 'Morada o habitación; predominantemente el Tabernáculo, el santuario portátil de Israel en el desierto', 'Derivado de la raíz שָׁכַן (''habitar, morar''), מִשְׁכָּן es el término primordial para el lugar donde la presencia de Dios reposa entre su pueblo. En su uso pentateucal dominante designa el santuario portátil del desierto — el Tabernáculo —, descrito con detalle minucioso en Éxodo 25-40 y referido a lo largo de Números y Levítico. En textos poéticos y proféticos, la palabra se amplía para significar cualquier morada o habitación: la morada celestial de Dios (Sal 26:8; 46:5), asentamientos humanos (Nm 24:5, el oráculo de Balaam sobre las tiendas de Israel) o incluso las moradas de los impíos (Job 18:21; 21:28).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4909', 'spa', 'מַשְׂכֹּרֶת — salario, paga por trabajo realizado; recompensa por fidelidad', 'Este sustantivo designa el salario o la paga obtenida mediante el servicio o el trabajo. Aparece exclusivamente en contextos narrativos relacionados con el servicio de Jacob a Labán y la fidelidad de Rut hacia Noemí. En Génesis, se refiere a la compensación acordada por el pastoreo de Jacob, repetidamente alterada por el engaño de Labán. En Rut, adquiere un sentido más elevado, aludiendo a la recompensa divina por la lealtad y el amor fiel al pacto. El término abarca tanto el pago comercial por labor realizada como el concepto más amplio de retribución por servicio leal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4910', 'spa', 'Gobernar, tener dominio, reinar; en Hifil, otorgar dominio o establecer como gobernante sobre alguien o algo. Un verbo de autoridad y poder que abarca', 'Gobernar, tener dominio, reinar; en Hifil, otorgar dominio o establecer como gobernante sobre alguien o algo. Un verbo de autoridad y poder que abarca toda la gama del gobierno: desde el dominio crudo sobre personas y cosas hasta la gobernación administrativa formal y la soberanía real. En Génesis 1:18 el sol y la luna ''gobiernan'' el día y la noche, mientras que en el Salmo 8:6 Dios ''hace al ser humano señorear'' sobre la creación (Hifil causativo). El español distingue consistentemente entre gobernar y dominar, reflejando los sentidos hebreos. Las traducciones árabes alternan de modo similar entre حَكَمَ (juzgar/gobernar) para contextos administrativos y مَلَكَ (reinar) para los reales, confirmando que se trata de usos genuinamente distintos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4911a', 'spa', 'Ser semejante, ser comparado, representar -- usado en Nifal, Hifil e Hitpael para semejanza y comparación.', 'Verbo que significa representar o ser semejante, y que aparece en varios troncos derivados que exploran distintas facetas de la comparación. En Nifal significa ''llegar a ser como'' o ''ser comparado con'', como en el estribillo inquietante del Salmo 49:12, 20, donde el hombre en su esplendor ''es semejante a las bestias que perecen''. El Hifil significa ''comparar'': Isaías 46:5 desafía a los idólatras: ''¿A quién me haréis semejante y me igualaréis?'' El Hitpael en Job 30:19 expresa el hacerse semejante al polvo y la ceniza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4911b', 'spa', 'Hablar en proverbios, componer parábolas o dichos poéticos; verbo denominativo de mashal (''proverbio, parábola'').', 'Verbo denominativo construido sobre el sustantivo mashal (''proverbio, parábola'') que significa componer o recitar discurso proverbial, ya sea una burla, una alegoría o una parábola profética. Su uso más concentrado se halla en Ezequiel, donde Dios ordena al profeta «propón una parábola» (Ez 17:2; 24:3) y donde el pueblo se queja de que Ezequiel no es más que «un hacedor de parábolas» (Ez 20:49). La aparición más temprana corresponde a Números 21:27, donde «los que hablan en proverbios» (moshelim) celebran la victoria de Israel. En español la acción se expresa como ''hablar en proverbio'', mientras que el francés y el alemán recurren a perífrasis, reflejando la dificultad de captar este concepto literario específicamente semítico en una sola palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4912', 'spa', 'Proverbio, parábola, oráculo profético o refrán; forma de discurso estructurado que va desde el dicho sapiencial hasta la burla', 'Proverbio, parábola, oráculo profético o refrán; forma de discurso estructurado que va desde el dicho sapiencial hasta la burla');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4916a', 'spa', 'Envío, empresa, emprendimiento -- especialmente aquello a lo que uno pone mano en su trabajo o sustento.', 'Sustantivo masculino constructo derivado de la raíz שָׁלַח (''enviar''), que denota el acto de extender la mano hacia algo, es decir, una empresa, emprendimiento u obra. Aparece casi exclusivamente en Deuteronomio dentro de la fórmula de bendición ''en toda obra de tu mano'' (Dt 12:7, 18; 15:10; 23:20; 28:8, 20), donde Dios promete bendecir todo aquello a lo que uno ponga mano. La única aparición en Isaías 7:25 pasa a un sentido concreto: un lugar para ''soltar'' ganado. El término subraya consistentemente actividad productiva y con propósito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4916b', 'spa', 'Extensión o envío, particularmente de la mano o de obsequios', 'Este término describe la acción de extender o enviar algo. Isaías lo usa para referirse a la conquista territorial: Edom y Moab serán ''la extensión de su mano'', es decir, territorio que tomarán bajo su dominio. Ester lo emplea para la alegre costumbre de ''enviar porciones'' de comida unos a otros durante las celebraciones de Purim. El sentido básico implica extensión o despacho: una mano que se extiende para asir, regalos que se envían para compartir. Abarca tanto la expansión agresiva como la distribución generosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4918', 'spa', 'Mesulam — nombre hebreo postexílico muy frecuente que significa ''recompensado, retribuido'', llevado por al menos nueve individuos distintos', 'Mesulam — nombre hebreo postexílico muy frecuente que significa ''recompensado, retribuido'', llevado por al menos nueve individuos distintos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4920', 'spa', 'מְשֶׁלֶמְיָהוּ / מְשֶׁלֶמְיָה — nombre propio, portero levita coraíta en tiempos de David', 'Este nombre propio, que significa aproximadamente «YHWH retribuye» o «YHWH restaura», pertenece a un levita que sirvió como portero en el tabernáculo y el servicio del templo. Aparece con ligeras variaciones y está asociado a la división coraíta de porteros del templo. Crónicas lo identifica como contemporáneo de David, quien organizó los turnos de portería. Es probablemente la misma persona llamada Selemías o Salum en otras genealogías. Las versiones griegas transliteran el nombre como Mesolam o Selemías, reflejando variaciones en la pronunciación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4923', 'spa', 'Devastación, desolación, ruina -- estado arruinado de una tierra asolada por juicio divino; también horror ante tal ruina.', 'Sustantivo femenino sinónimo de שַׁמָּה, que denota devastación, desolación o el yermo espantoso que queda tras el juicio divino. Ezequiel lo emplea repetidamente al pronunciar sentencia sobre la tierra de Israel: ''haré la tierra desolación y ruina'' (Ez 6:14; 33:28-29; 35:3, 7). En Ezequiel 5:15 se extiende para significar el ''horror'' que el destino de Jerusalén provocará entre las naciones. El plural מְשַׁמּוֹת aparece en Isaías 15:6 y Jeremías 48:34 para las aguas secas y arruinadas de Moab. El término abarca tanto la ruina física como la conmoción emocional que produce.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4924b', 'spa', 'מִשְׁמָן — gordura, robustez; personas corpulentas/vigorosas o lugares fértiles', 'Este sustantivo deriva de la raíz que significa «grasa» o «aceite» y posee significados tanto abstractos como concretos: la cualidad de gordura, o referencias concretas a personas robustas y bien alimentadas, o a regiones fértiles. En la literatura profética aparece en contextos de juicio contra la arrogancia y la fuerza, o describiendo la riqueza de tierras conquistadas. Puede designar individuos prósperos y corpulentos, a menudo con connotaciones negativas de orgullo o complacencia, o describir metafóricamente las partes más ricas y deseables de un territorio. La imagen conecta consistentemente la abundancia física con el juicio o la bendición divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4927', 'spa', 'מִשְׁמָע — nombre propio en las genealogías ismaelita y simeonita', 'Misma es un nombre propio que aparece en dos contextos genealógicos distintos en la Biblia hebrea. El nombre, que posiblemente significa «audición» o «noticia», identifica tanto a un ancestro tribal ismaelita (hijo de Ismael) como a un jefe de clan simeonita. Este doble uso refleja el patrón bíblico frecuente de nombres que aparecen en diferentes linajes tribales. La Septuaginta lo transcribe como Masama o Masmán, preservando el nombre en transliteración griega. Aunque solo figura en listas genealógicas, representa identidades familiares o clánicas reconocidas, conservadas en los registros tribales de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4928', 'spa', 'מִשְׁמַעַת — guardia personal, cuerpo de obediencia; los obligados a servir o someterse', 'Este sustantivo, derivado de la raíz «oír/obedecer», designa un grupo de personas ligadas por la obediencia, ya sea una unidad de guardia militar o súbditos bajo autoridad. El término enfatiza la relación de servicio disciplinado y sumisión, más que la condición genérica de soldado. Aparece en contextos que describen unidades militares selectas al servicio cercano del rey (la guardia de David), y metafóricamente en profecía para describir la futura sujeción de pueblos enemigos. El concepto une escucha, obediencia y servicio leal en un solo término que designa a quienes obedecen a su comandante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4929', 'spa', 'Guardia, vigilia o puesto de vigilancia; lugar de reclusión o custodia; puesto asignado o deber de servicio', 'Guardia, vigilia o puesto de vigilancia; lugar de reclusión o custodia; puesto asignado o deber de servicio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4931', 'spa', 'Guarda, vigilia, encargo, deber; una obligación o puesto de responsabilidad, especialmente el servicio levítico; también custodia, resguardo y ordenan', 'Guarda, vigilia, encargo, deber; una obligación o puesto de responsabilidad, especialmente el servicio levítico; también custodia, resguardo y ordenanza divina. Mishmeret es el sustantivo de obligación derivado de שָׁמַר (''guardar, custodiar''), y lleva toda la gama de ese verbo a forma institucional. En su centro está el encargo levítico: el deber sagrado de custodiar y mantener el tabernáculo, su mobiliario y sus límites. Números 3-4 y 18 usan mishmeret decenas de veces para definir lo que los clanes levíticos deben proteger, transportar y servir. Pero el alcance se extiende: Dios confía su mishmeret a Abraham (Gn 26:5) como mandamiento divino; el maná se deposita en mishmeret para resguardo (Éx 16:32-34); centinelas se apostaban en sus puestos de mishmeret (Is 21:8; Hab 2:1); y los cantores del templo rotaban en sus turnos de mishmeret (1 Cr 25:8; Neh 12:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4932', 'spa', 'Doble, copia, segundo; sustantivo que denota cantidad doble, rango ordinal o duplicado escrito', 'Doble, copia, segundo; sustantivo que denota cantidad doble, rango ordinal o duplicado escrito');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4933', 'spa', 'Saqueo, despojo, botín: bienes arrebatados por conquista, especialmente como expresión de juicio divino sobre un pueblo', 'Sustantivo femenino que designa el saqueo, despojo o botín, es decir, los bienes y posesiones arrebatados durante una conquista militar o incursión. Aparece principalmente en pronunciamientos proféticos de juicio divino, donde ser entregado ''al saqueo'' señala vulnerabilidad total ante los enemigos. En 2 Reyes 21:14, Dios declara que hará del remanente de Israel ''saqueo y despojo para todos sus enemigos''. Isaías 42:22, 24 lamenta a Jacob entregado al saqueo sin quien lo libre. Jeremías 30:16 promete una inversión: quienes saquearon a Israel serán ellos mismos despojados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4937a', 'spa', 'מִשְׁעָן — apoyo, bastón, sustento (literal o figurado)', 'Este sustantivo masculino significa ''apoyo'' o ''bastón'', refiriéndose a aquello que sostiene o sustenta. Si bien la imagen básica es la de un bastón o soporte físico, el uso bíblico se extiende rápidamente al ámbito metafórico: Dios como apoyo en la aflicción, o las provisiones esenciales (pan y agua) como los pilares de la vida. El término aparece exclusivamente en textos poéticos (Samuel, Salmos, Isaías), donde funciona tanto en sentido literal —bastón como soporte— como en sentido figurado —Dios o los recursos básicos como aquello que sustenta la vida. Isaías 3:1 lo emplea en un juego de palabras enumerando los diversos tipos de ''apoyo'' que serán removidos de Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4938b', 'spa', 'Bastón, cayado, vara de apoyo — una vara usada para caminar, apoyarse o como instrumento de autoridad y ayuda', 'El sustantivo מִשְׁעֶנֶת (mish''enet) designa un bastón o cayado — algo en lo que uno se apoya. Un hombre herido camina con su bastón durante la recuperación (Éx 21:19). Los príncipes cavan un pozo con sus báculos (Nm 21:18). Eliseo envía a Giezi con su bastón para ponerlo sobre el niño muerto (2 R 4:29-31). La «vara y el cayado» del pastor consuelan en el Salmo 23:4. Los ancianos se sientan con bastones en la Jerusalén restaurada (Zac 8:4). En sentido negativo, Egipto es una «caña de bastón quebrada» que traspasa la mano de quien se apoya (2 R 18:21; Is 36:6; Ez 29:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4940', 'spa', 'Clan, grupo familiar; unidad de parentesco mayor que un hogar pero menor que una tribu, la división social básica de Israel', 'מִשְׁפָּחָה designa el pilar social fundamental del Israel antiguo: el clan o grupo familiar extenso a través del cual fluían la identidad, la tierra y las obligaciones. Con más de 300 apariciones, estructura los censos de Números, los repartos tribales de Josué y los oráculos proféticos dirigidos a pueblos enteros (Am 3:1-2). Se sitúa como unidad intermedia de parentesco entre el hogar individual (בַּיִת) y la tribu (שֵׁבֶט/מַטֶּה). El Año del Jubileo restaura a cada persona a su מִשְׁפָּחָה (Lv 25:10). Un uso metafórico aislado extiende el término a categorías no humanas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4941', 'spa', 'Justicia, juicio, ordenanza; decisión judicial, caso legal, regulación prescrita o costumbre establecida', 'Uno de los sustantivos de mayor peso teológico de la Biblia hebrea, מִשְׁפָּט abarca todo el arco de la vida jurídica: desde el ideal abstracto de justicia que Dios encarna (Gn 18:25) hasta el veredicto concreto que dicta un juez, pasando por el cuerpo de ordenanzas que estructuran la vida del pacto de Israel. También puede describir la costumbre o el modo habitual, como cuando el copero del faraón es restaurado ''conforme a la costumbre anterior'' (Gn 40:13). La amplitud del término recuerda que en el pensamiento bíblico la justicia nunca es meramente teórica: siempre se promulga, se codifica y se vive.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4945a', 'spa', 'Copero, oficial de la corte real encargado de servir el vino al rey y protegerlo del envenenamiento.', 'Derivado del Hifil de shaqah (''dar de beber''), este sustantivo designa al copero — un funcionario de alto rango en la corte responsable de probar y servir el vino al rey. En la narrativa de José (Gn 40–41), el copero del faraón desempeña un papel decisivo en la liberación de José de la prisión. Los coperos de Salomón impresionaron tanto a la reina de Sabá que quedó sin aliento (1 R 10:5). La posición de Nehemías como copero de Artajerjes (Neh 1:11) le otorgó acceso e influencia únicos en la corte persa, posibilitando su misión de reconstruir los muros de Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4945b', 'spa', 'Bebida, líquido para beber o contenido de vasijas; también tierra bien regada o irrigación, enfatizando el agua para la fertilidad.', 'Sustantivo derivado de la raíz ''dar de beber,'' que abarca tanto lo que se bebe como la tierra que ha sido regada. En su sentido de bebida, describe las vasijas de la corte de Salomón (1 R 10:21; 2 Cr 9:20), el líquido que puede contaminar ritualmente un alimento (Lv 11:34) y la bebida negada al sediento (Is 32:6). En su sentido de irrigación, retrata la fértil llanura del Jordán como ''toda bien regada, como el jardín del SEÑOR'' (Gn 13:10). El español capta bien la distinción: ''bebida'' para el líquido y ''regada'' para la tierra irrigada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4947', 'spa', 'El dintel, la viga horizontal sobre el marco de una puerta', 'Este término arquitectónico aparece exclusivamente en el relato de la Pascua en Éxodo 12, donde designa la viga horizontal sobre la abertura de la puerta. Cuando se ordenó a los israelitas poner sangre del cordero en sus casas como protección contra la plaga, debían aplicarla en ''los dos postes y el dintel''. El dintel, junto con los postes laterales, enmarcaba la entrada y llevaba la sangre que señalaba los hogares bajo protección divina. Este humilde elemento arquitectónico se convirtió en pieza central de la narrativa de la liberación del Éxodo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4948', 'spa', 'Peso: la pesantez medible de un objeto, frecuentemente especificada en oro, plata o bronce. Mishqal es el sustantivo hebreo para el peso medible, deri', 'Peso: la pesantez medible de un objeto, frecuentemente especificada en oro, plata o bronce. Mishqal es el sustantivo hebreo para el peso medible, derivado del verbo שָׁקַל (''pesar''). Sus 49 apariciones se agrupan en torno a inventarios y descripciones de objetos preciosos: el peso del anillo y los brazaletes de Rebeca (Gn 24:22), la barra de oro robada en Jericó (Jos 7:21), la cota de malla de Goliat de cinco mil siclos (1 Sam 17:5) y los ingresos anuales de oro de Salomón de 666 talentos (1 Re 10:14). Las ofrendas del tabernáculo en Números 7 representan once de sus apariciones, cada plato y tazón especificado por peso. En el ámbito ético, Levítico 19:35 ordena justicia ''en el peso'', y Ezequiel 5:1 prescribe ''balanzas de peso'' para el acto simbólico del profeta. Notablemente, Job 28:25 atribuye peso incluso al viento, una afirmación poética de que Dios mide lo inconmensurable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4953', 'spa', 'מַשְׁרוֹקִיתָא — flauta, instrumento de viento en la orquesta de Nabucodonosor', 'Este sustantivo arameo designa una flauta o caramillo, un instrumento musical de viento que aparece exclusivamente en el relato de Daniel 3 sobre la ceremonia de dedicación de la estatua de oro de Nabucodonosor. El término forma parte de la lista repetida de instrumentos de la orquesta real babilónica, cuya música servía como señal para que los súbditos se postraran en adoración. La palabra aparece en formas enfáticas y absolutas a lo largo de cuatro versículos. Existen formas relacionadas en siríaco, y la raíz sugiere un sonido de silbido o soplo. Este instrumento de viento era parte del conjunto musical internacional que caracterizaba las cortes reales del antiguo Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4959', 'spa', 'Palpar o tocar físicamente (Qal); tantear, buscar a tientas (Piel); hacer palpar o tocar (Hifil)', 'Un verbo táctil que abarca desde el toque suave hasta el tanteo desesperado. En su forma básica Qal, es Isaac extendiendo la mano para palpar las manos de Jacob, comprobando si realmente es Esaú (Gn 27:12, 22): un gesto íntimo, deliberado, lleno de incertidumbre. El Piel intensifica esto en una búsqueda a tientas: Labán revolviendo la tienda de Raquel (Gn 31:34), o los ciegos tanteando al mediodía como maldición del pacto (Dt 28:29). Job lo aplica a los malvados que tropiezan en la oscuridad (Job 5:14, 12:25). El Hifil adopta un valor causativo: Sansón pide a un muchacho que le deje palpar las columnas (Jue 16:26), y la plaga egipcia trae una oscuridad tan densa que se puede «hacer sentir» (Éx 10:21). El árabe mass (''tocar'') y el arameo məshash confirman el núcleo háptico de la raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4960', 'spa', 'Banquete o festín centrado en la bebida; menos frecuentemente, la bebida misma, a diferencia de la ocasión festiva', 'Banquete o festín centrado en la bebida; menos frecuentemente, la bebida misma, a diferencia de la ocasión festiva');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4962', 'spa', 'Varones, hombres o personas colectivamente; en la expresión constructa mete mispar, pocos en número; poéticamente, los mortales', 'Varones, hombres o personas colectivamente; en la expresión constructa mete mispar, pocos en número; poéticamente, los mortales');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4964', 'spa', 'מֶתֶג — freno, brida; instrumento de control para animales o (figuradamente) personas', 'Este sustantivo masculino designa un freno o brida, el dispositivo que se coloca en la boca de un animal para controlar sus movimientos. El término aparece tanto en contextos literales (para dominar caballos y asnos) como en poderosas metáforas (Dios controlando a reyes enemigos, o la necesidad de refrenar a los necios). La imagen enfatiza el control, la restricción y la sumisión de una criatura obstinada a una dirección externa. Proverbios y Salmos lo utilizan para ilustrar la necesidad de restricción externa para quienes carecen de sabiduría interior, mientras que los textos proféticos lo emplean para mostrar el dominio soberano de Dios sobre naciones arrogantes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4966', 'spa', 'Dulce, dulzura — agradable al gusto; de la miel, las palabras de Dios, el habla amable y el gozo de vivir', 'El adjetivo y sustantivo מָתוֹק (matoq) describe lo que es dulce al paladar o metafóricamente agradable. La adivinanza de Sansón gira en torno a la paradoja: «Del fuerte salió algo dulce», cuya respuesta es la miel (Jue 14:14, 18). El salmista declara que los juicios de Dios son más dulces que la miel (Sal 19:10). Proverbios llama a las palabras amables «dulzura para el alma y medicina para los huesos» (Pr 16:24), mientras que Eclesiastés observa que el sueño del trabajador es dulce (Ecl 5:12). Isaías advierte contra llamar «dulce a lo amargo y amargo a lo dulce» (Is 5:20).');